-- Sections: guide-1200-to-1400-roadmap (25 sections, 3073 words)
insert into public.sat_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select v.id, v.page_id, v.block_type, v.heading, 'published', v.sort_order, v.content, v.metadata
from (
  values
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '1')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Who this roadmap is for$sat_pb$, 1, $sat_pb${"markdown":"You have a real score or a full-length practice score around **1150–1250**, and your target is **1400**. That means adding roughly 150–250 points, or about 75–125 per section if you split the work evenly. The public module [Score Goals and Study Plans](/score-goals-and-study-plans) explains how to set a target; this roadmap is the operating system for reaching this particular one.\n\n**A plain warning about promises.** No honest guide can tell you how many weeks this will take. It depends on your starting profile, your hours and the quality of your review. What this roadmap gives you is a method whose progress you can *measure every two weeks*, so you always know whether it is working."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":1}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '2')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$What a 1400 looks like in the score structure$sat_pb$, 2, $sat_pb${"markdown":"The SAT total runs from 400 to 1600 and is the sum of two section scores, each from 200 to 800. A 1400 is, for example, 700 + 700, 720 + 680 or 680 + 720. A 1200 is often around 600 + 600, or an uneven split such as 650 + 550.\n\n**First decision: even or uneven gain?** Look at your two section scores.\n- If they differ by **80 points or more**, most of your gain should come from the weaker section first, because it usually has more reachable points.\n- If they are **within 50 points**, run both sections in parallel, with slightly more time on the one where your errors are mostly *content* gaps (they are cheaper to fix than reading-speed problems)."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":2}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '3')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Why the adaptive design matters for this jump$sat_pb$, 3, $sat_pb${"markdown":"Each section has two modules. The College Board describes the first as a broad mix of easy, medium and hard questions, and says your performance on it determines whether the second module is harder or easier on average.\n\nFor a student moving from 1200 to 1400, this means:\n- **First-module accuracy is your foundation.** Careless errors on easy and medium questions in module 1 cost the point *and* weaken the performance that routes you.\n- **You must become comfortable in the harder module.** Students near 1200 often see a mix of routings. At 1400 you should expect the harder second module in both sections much of the time, so your practice must include hard questions, not just volume of medium ones."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":3}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '4')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$The two-week cycle: diagnose, fix, test$sat_pb$, 4, $sat_pb${"markdown":"The whole roadmap runs on one repeating cycle.\n\n| Days | Phase | What you do |\n|---|---|---|\n| 1 | Diagnose | Full timed mock, then classify every miss |\n| 2–11 | Fix | Targeted work on the top two error sources |\n| 12–13 | Test | Timed modules on the fixed skills |\n| 14 | Reset | Review the cycle, choose next targets |\n\nEach cycle should end with **evidence**: did the targeted error type become rarer? If yes, move to the next one. If no, change the fix, not the target."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":4}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '5')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Step 1 (Diagnose): taking a diagnostic mock that is worth reviewing$sat_pb$, 5, $sat_pb${"markdown":"- Use a **full-length adaptive test**: either an official Bluebook practice test or a full mock in the [Schood SAT simulator](https://sat.schood.online). Alternate between them across cycles so you see both sources.\n- Take it in **one sitting**, timed, with a 10-minute break between sections as on the real test.\n- **Mark every question you guessed on** with a note, even if you got it right. A lucky correct answer is still a weakness.\n- Do not check answers during the break."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":5}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '6')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Step 2 (Diagnose): classifying every miss$sat_pb$, 6, $sat_pb${"markdown":"Every missed or guessed question gets exactly one cause:\n\n| Cause | Definition | Typical fix |\n|---|---|---|\n| **Content (C)** | You did not know the rule, formula or skill | Learn it from the matching module, then drill it |\n| **Process (P)** | You knew it but set up or read it wrongly | Build a checking habit for that question type |\n| **Time (T)** | You ran out of time or rushed | Pacing changes, faster routines |\n| **Careless (X)** | Arithmetic slip, mis-click, misread choice | Specific check, not \"be careful\" |\n| **Guess-right (G)** | Correct but unsure | Treat as a miss for review |\n\n**Rule:** \"careless\" is only allowed when you can name the exact slip (\"copied −3 as 3\"). If you cannot name it, it is a process error."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":6}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '7')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Step 3 (Diagnose): finding the two targets for the cycle$sat_pb$, 7, $sat_pb${"markdown":"Count your misses by **domain** and by **cause**. Then weigh each domain by its official share of the test:\n\n- **Math:** Algebra about 35%, Advanced Math about 35%, Problem-Solving and Data Analysis about 15%, Geometry and Trigonometry about 15%.\n- **Reading and Writing:** Craft and Structure about 28%, Information and Ideas about 26%, Standard English Conventions about 26%, Expression of Ideas about 20%.\n\n**Priority score** for each domain = (your misses in it) × (its weight). Your two highest priority scores are the cycle's targets. The official score report's Knowledge and Skills section, which shows performance in the eight content areas, is a good cross-check when you have a real test score.\n\n**Typical 1200-level profile (common, not universal):** Standard English Conventions and Algebra are often the cheapest points available, because the skills are rule-based and the questions appear early in each skill group. If they are among your misses, fix them first."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":7}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '8')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Step 4 (Fix): the targeted-practice day$sat_pb$, 8, $sat_pb${"markdown":"Each fix day (about 60–90 minutes) has the same shape:\n\n1. **Learn (15–20 min):** read the matching public module section, for example [Standard English Conventions](/reading-writing-conventions) for boundaries.\n2. **Drill (30–40 min):** in the [SAT Practice Bank](https://practice.sat.schood.online/bank), filter to the target domain and skill. Start at medium difficulty; move to hard when you reach about 85% accuracy over 20 questions.\n3. **Review (15–20 min):** every miss goes into the error log with a cause code and a *rule sentence* (see the next section).\n4. **Spaced review (5–10 min):** clear the items due in [Reviews](https://practice.sat.schood.online/reviews).\n\n**Volume guide:** 20–30 questions per fix day is enough. Quality of review matters more than count."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":8}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '9')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Step 5 (Fix): the error log that actually changes behaviour$sat_pb$, 9, $sat_pb${"markdown":"A useful error log is short and forces a rule. Use the [SAT Practice notebook](https://practice.sat.schood.online/notebook) or a paper notebook with these fields:\n\n| Field | Example |\n|---|---|\n| Date and source | Cycle 2, mock 1, Math M2 Q14 |\n| Domain and skill | Advanced Math, nonlinear equations |\n| Cause code | P |\n| What I did | Set discriminant of x² − 6x + k + 3 instead of the combined equation |\n| Rule sentence | \"Before using b² − 4ac, write the single combined equation.\" |\n| Re-solve date | 2 days later, without notes |\n| Re-solve result | Correct / still wrong |\n\n**The rule sentence is the point of the log.** If a miss does not produce a sentence you can apply to the *next* question of that type, the review is not finished.\n\n**Re-solve:** two days after logging, redo the question from scratch with no notes. Only a correct re-solve closes the entry."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":9}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '10')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Step 6 (Test): proving the fix worked$sat_pb$, 10, $sat_pb${"markdown":"On days 12–13 of each cycle:\n- Take **one timed module** in each section (27 R&W questions in 32 minutes; 22 Math questions in 35 minutes) using SAT Practice or a module from a Bluebook test you have not seen.\n- Count misses **in the two target domains only**. Compare with the diagnostic.\n- If target misses dropped clearly, the fix worked; keep a maintenance dose (10 questions twice a week) and choose new targets.\n- If not, change the fix: more learning time, a different explanation source, or a slower untimed drill."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":10}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '11')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$A worked cycle, start to finish$sat_pb$, 11, $sat_pb${"markdown":"Here is how one cycle looks in practice for an illustrative student, \"Aziz\", whose diagnostic mock gave 610 R&W and 590 Math. The details are an example of the method, not a prediction of results.\n\n**Day 1: diagnose.** Aziz takes a full simulator mock. He marks nine questions as guesses.\n\n**Day 2: classify.** He logs every miss and guess. In R&W, most entries are boundaries and transitions (mainly C codes: he did not know the semicolon-before-*however* rule). In Math, most entries are systems and linear functions, with many P codes (he set up correct equations but solved for the wrong variable).\n\n**Day 3: choose targets.** Weighting by domain share, his two targets are **Standard English Conventions** (R&W) and **Algebra** (Math). He writes them at the top of his notebook page.\n\n**Days 4–11: fix.** Each day he reads the matching section of a public module for 15 minutes, drills 20–25 Bank questions in the target, and writes rule sentences. Two of his rule sentences: *\"Two complete clauses + however = semicolon before, comma after.\"* and *\"Circle the variable the question asks for before solving.\"*\n\n**Days 12–13: test.** One timed module per section. He counts misses in his two targets only and compares them with the diagnostic.\n\n**Day 14: reset.** Conventions misses dropped sharply, so conventions moves to maintenance (10 questions twice a week). Algebra P codes dropped less, so Algebra stays a target for one more cycle, now with a new fix: he solves every system twice, once by algebra and once in Desmos, to catch setup errors. His second target becomes **Information and Ideas**, the next-highest priority score.\n\n**What to copy from this example:** the targets came from counted, weighted data; every fix produced a sentence; and the decision at the end of the cycle followed the evidence, not a feeling."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":11}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '12')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$A review session, minute by minute$sat_pb$, 12, $sat_pb${"markdown":"A 60-minute review session after a timed module looks like this:\n\n- **0–5 min:** list every miss and guess with its question number.\n- **5–30 min:** re-solve each one *before* reading any explanation. Note which ones you can now solve with time. Those are usually P or T codes.\n- **30–45 min:** read explanations only for the questions you still cannot solve. Assign C codes to these.\n- **45–55 min:** write one rule sentence per entry.\n- **55–60 min:** schedule re-solve dates for every entry.\n\n**If you are short on time,** cut the number of questions you review, not the steps. Ten fully reviewed questions teach more than thirty skimmed ones."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":12}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '13')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Choosing practice material$sat_pb$, 13, $sat_pb${"markdown":"Use each resource for what it does best:\n\n| Resource | Best use in this roadmap |\n|---|---|\n| Official Bluebook practice tests | Full diagnostic mocks with the real interface |\n| Schood SAT simulator | Additional full adaptive mocks |\n| SAT Practice Bank | Targeted drills by domain, skill and difficulty |\n| SAT Practice Reviews | Spaced repetition of missed items |\n| College Board Student Question Bank | Extra official questions by domain and skill |\n| Public Playbook modules | Learning the rule or method before drilling |\n\n**Keep official tests for mocks.** If you drill from questions that appear in a Bluebook practice test, that test will no longer give an honest score estimate."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":13}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '14')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Weekly targets$sat_pb$, 14, $sat_pb${"markdown":"Targets here are *process* targets you control. Score targets come only from full tests.\n\n| Target | Each week |\n|---|---|\n| Study hours | 8–10 hours, in 5–6 sessions |\n| Targeted questions | 100–150 in the cycle's two domains |\n| Error-log entries | Every miss and every guess logged with a rule sentence |\n| Re-solves | All entries from the previous week re-solved |\n| Timed work | At least one timed module per section |\n| Spaced reviews | Reviews queue cleared at least four days a week |\n\n**Weekly checkpoint (15 minutes, same day each week):** count entries by cause code. A falling share of P and X codes means your habits are improving even before your score moves."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":14}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '15')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$The Reading and Writing plan for this jump$sat_pb$, 15, $sat_pb${"markdown":"**Phase A (cycles 1–2): conventions and transitions.** Boundaries and form/structure/sense rules are learnable in weeks. Aim for near-complete accuracy on medium conventions questions; they are among the fastest points on the test.\n\n**Phase B (cycles 2–3): evidence and data.** Command of evidence (textual and quantitative) rewards a precise method: restate the claim, then choose the evidence that addresses exactly that claim. The premium [R&W Hard-Module Traps](/guide-rw-hard-module-traps) guide shows the true-but-irrelevant trap, a frequent source of lost points at this level.\n\n**Phase C (cycles 3–4): words in context, structure, cross-text.** These depend on careful reading more than rules. Practise short daily sets rather than long weekly ones.\n\n**Reading habit:** 20 minutes a day of varied nonfiction (science journalism, history, economics) builds the reading stamina that drills cannot."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":15}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '16')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$The Math plan for this jump$sat_pb$, 16, $sat_pb${"markdown":"**Phase A (cycles 1–2): linear algebra to automatic.** Linear equations, linear functions, systems and inequalities. These appear at every difficulty level, and at 1400 you cannot miss medium ones. Work through [Math: Algebra](/math-algebra).\n\n**Phase B (cycles 2–3): Advanced Math core.** Quadratics (factoring, vertex form, discriminant), exponential models, function notation and equivalent expressions. See [Math: Advanced Math](/math-advanced-math).\n\n**Phase C (cycles 3–4): data and geometry essentials.** Percentages, ratios, mean and median, area and volume, right triangles and circles. Smaller domains, but cheap points once the formulas are memorised (and the reference sheet is checked).\n\n**Desmos throughout.** Learn the basic routines in [Desmos and Calculator Strategy](/desmos-and-calculator-strategy): graphing both sides of an equation, finding intersections and reading a vertex. These alone remove many process errors."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":16}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '17')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Pacing upgrades between 1200 and 1400$sat_pb$, 17, $sat_pb${"markdown":"- **R&W:** about 71 seconds per question on average. Conventions items should become fast (30–45 seconds), freeing time for evidence and cross-text items.\n- **Math:** a little over 95 seconds per question on average. Move quickly through early items, but never skip re-reading an SPR entry.\n- **Use mark for review.** If a question passes about two minutes, choose your best answer, mark it and move on. Return only after finishing the module.\n- **No blanks.** The College Board advises answering every question as well as you can; an empty answer cannot earn credit."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":17}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '18')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$What to stop doing$sat_pb$, 18, $sat_pb${"markdown":"- **Stop taking full tests without full review.** A mock you do not review is a four-hour way to practise your current mistakes. One reviewed mock every two weeks beats three unreviewed ones.\n- **Stop reading explanations and calling it review.** Reading an explanation feels like learning; re-solving the question two days later is learning.\n- **Stop drilling only what you are good at.** It feels productive and changes nothing. Follow the priority score.\n- **Stop memorising long vocabulary lists.** Words in context tests meaning in a sentence; reading widely and drilling the question type works better.\n- **Stop saying \"careless\".** Name the slip or call it a process error.\n- **Stop changing answers on a feeling.** Change only when you can point to a specific reason.\n- **Stop avoiding the calculator.** It is permitted on every Math question."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":18}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '19')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$What to start doing$sat_pb$, 19, $sat_pb${"markdown":"- Logging *guessed* correct answers as misses.\n- Writing one rule sentence per miss.\n- Re-solving every logged question after two days.\n- Ending each week with a 15-minute checkpoint.\n- Practising at least some hard questions every week from the first cycle on, so the harder module never feels foreign."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":19}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '20')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$A sample eight-week sequence$sat_pb$, 20, $sat_pb${"markdown":"This is one example of four cycles for a student starting at 600 R&W and 600 Math. Adjust targets to your own diagnosis.\n\n| Week | R&W focus | Math focus | Test |\n|---|---|---|---|\n| 1 | Boundaries | Linear equations and systems | Diagnostic mock (day 1) |\n| 2 | Form, structure and sense | Linear functions, inequalities | Timed modules (end of week) |\n| 3 | Transitions, rhetorical synthesis | Quadratics, discriminant | Mock 2 (start of week) |\n| 4 | Command of evidence (textual) | Exponential models | Timed modules |\n| 5 | Quantitative evidence | Percentages, ratios, units | Mock 3 |\n| 6 | Words in context, structure | Statistics and probability | Timed modules |\n| 7 | Cross-text, inferences | Geometry and trigonometry | Mock 4 |\n| 8 | Mixed hard sets | Mixed hard sets | Timed modules, final review |\n\nFor a ready-made schedule with day-by-day tasks, open the [Eight-Week Standard plan](/plans/eight-week-standard), or the [Twelve-Week Foundation plan](/plans/twelve-week-foundation) if you have more time."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":20}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '21')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Reading your progress honestly$sat_pb$, 21, $sat_pb${"markdown":"- **Use full tests for score estimates,** not module scores or bank accuracy.\n- **Expect noise.** Scores vary from test to test; College Board score reports show a score range for exactly this reason. Judge the trend over two or three mocks, not one.\n- **Watch the cause mix.** If C codes are falling but P codes are not, you are learning content but not yet applying it under time. Add more timed modules.\n- **Plateaus are information.** If two cycles pass with no change in the target domain, change the method: different explanations, slower practice, or a tutor review of your error log."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":21}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '22')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Common profiles and what to do$sat_pb$, 22, $sat_pb${"markdown":"**\"Strong Math, stuck R&W\" (for example 680 Math, 540 R&W).** Put 65–70% of hours into R&W. Conventions first, then evidence. Keep Math alive with 2 short sessions a week.\n\n**\"Strong R&W, stuck Math\" (for example 650 R&W, 560 Math).** Put 65–70% into Math. Algebra and Advanced Math cover around 70% of the section; start there. Learn the Desmos routines early. The [Math Priority plan](/plans/math-priority) is built for this profile.\n\n**\"Even but slow\" (600/600, runs out of time).** Your issue is often process, not content. Add a timed module in each section every week from the first cycle, and practise routines (Desmos moves, the claim-first method in R&W) until they are automatic.\n\n**\"Even and accurate but stuck at medium\" (high accuracy on medium, low on hard).** Move to hard-only drills sooner, and read the two hard-module guides."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":22}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '23')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$checklist$sat_pb$, $sat_pb$Checkpoints before moving to the next roadmap$sat_pb$, 23, $sat_pb${"items":["Two consecutive full mocks at or above about 1380.","Conventions accuracy high and stable on medium and hard questions.","No more than an occasional miss on medium Algebra questions.","Error log shows P and X codes falling across three cycles.","Comfortable finishing both sections on time with a few minutes to check.","All error-log entries from the last two weeks re-solved correctly.","When all of these hold, move on to the 1400 to 1550 Roadmap."]}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":23}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '24')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Frequently asked questions$sat_pb$, 24, $sat_pb${"markdown":"**How many hours a week do I need?** Most of the structure above assumes 8–10 hours. With 5–6 hours, stretch each cycle to three weeks rather than cutting review.\n\n**Should I take a full mock every week?** Not in the fix phase. One full mock per two-week cycle, plus timed modules, gives you enough data without stealing review time.\n\n**Is SAT Practice or the official question bank better?** Use both. The College Board Student Question Bank filters by domain, skill and difficulty; Schood SAT Practice adds reviews, a notebook and daily sessions. Avoid repeating questions from Bluebook practice tests you plan to use as mocks.\n\n**When should I book the test?** When your plan leaves at least two full cycles before the test date, and your last two mocks are close to your target. The [Final 14 Days](/guide-final-14-days) guide covers the last stretch."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":24}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$ || ':' || '25')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1200-to-1400-roadmap$sat_pb$)::uuid, $sat_pb$callout$sat_pb$, $sat_pb$Summary$sat_pb$, 25, $sat_pb${"label":"The method in one line","body":"Diagnose with a reviewed full mock, fix the two highest-priority domains for ten days, prove the fix with timed modules, and repeat. Measure process every week and score every two weeks."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":25}$sat_pb$::jsonb)
) as v(id, page_id, block_type, heading, sort_order, content, metadata)
where exists (select 1 from public.sat_playbook_pages p where p.id = v.page_id)
on conflict do nothing;

-- Sections: guide-1400-to-1550-roadmap (27 sections, 3187 words)
insert into public.sat_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select v.id, v.page_id, v.block_type, v.heading, 'published', v.sort_order, v.content, v.metadata
from (
  values
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '1')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Who this roadmap is for$sat_pb$, 1, $sat_pb${"markdown":"You score around **1380–1450** on full tests and want **1500–1550 or above**. You probably reach the harder second module in both sections most of the time, rarely miss easy questions, and lose most points to a handful of hard items and the occasional slip.\n\nAt this level the problem changes shape. Below 1400, the main question is *what don't I know?* Above it, the main question is *why did I miss something I know?* The [1200 to 1400 Roadmap](/guide-1200-to-1400-roadmap) built the system; this one sharpens it into a precision tool.\n\n**No score promises.** Nobody can guarantee a 1550. What this roadmap can do is remove the predictable sources of lost points and give you a way to measure whether that is happening."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":1}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '2')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$The arithmetic of the last 150 points$sat_pb$, 2, $sat_pb${"markdown":"A 1550 is, for example, 780 + 770 or 760 + 790. Each section is out of 800. Two consequences:\n\n- **Each remaining miss matters more.** You may have only a few misses left in a section, so removing even one or two error *types* is a big change.\n- **Variance matters as much as average.** A student who scores 1520, 1460 and 1540 on three mocks has the ability for 1540 but not the reliability. Reducing bad days is as valuable as raising good ones.\n\nAlso remember that each module includes a small number of **unscored pretest questions** (the College Board specifications describe two per module) that you cannot identify. Treat every question as if it counts."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":2}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '3')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Your three enemies at this level$sat_pb$, 3, $sat_pb${"markdown":"1. **The hard-module trap.** Questions designed so the obvious method gives a plausible wrong answer (see the two hard-module guides).\n2. **The slip.** A known skill applied wrongly once per test: a sign, a misread \"not\", an SPR entry.\n3. **The time squeeze.** Spending three minutes on one item and rushing the last two.\n\nEach cycle in this roadmap attacks one or more of these with a specific tool."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":3}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '4')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$The precision cycle: diagnose, fix, test (two weeks)$sat_pb$, 4, $sat_pb${"markdown":"| Days | Phase | Focus |\n|---|---|---|\n| 1 | Diagnose | Full adaptive mock under strict conditions |\n| 2 | Diagnose | Forensic review of every miss, guess and slow question |\n| 3–10 | Fix | Hard-only drills on the cycle's targets; zero-careless protocol |\n| 11 | Test | Two timed upper-level modules (one per section) |\n| 12–13 | Fix | Close remaining gaps from the test day |\n| 14 | Reset | Variance and trend review |\n\nCompared with the 1200–1400 cycle, the review is deeper (a whole day), the drills are harder and the test phase examines **slow** questions as well as wrong ones."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":4}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '5')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Step 1: Mocks under strict conditions$sat_pb$, 5, $sat_pb${"markdown":"- Use full adaptive tests only: official Bluebook practice tests and full mocks in the [Schood SAT simulator](https://sat.schood.online).\n- Take them at the **time of day of your real test**, in one sitting, with the scheduled 10-minute break and nothing else.\n- No pausing, no phone, no checking answers mid-test.\n- Mark guesses *and* any question where you hesitated between two choices."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":5}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '6')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Step 2: Forensic review$sat_pb$, 6, $sat_pb${"markdown":"At this level, a miss list is not enough. For every **missed**, **guessed** or **slow** question (more than about two minutes in Math, more than about 90 seconds in R&W), record:\n\n| Field | Purpose |\n|---|---|\n| Question type and domain | Pattern spotting |\n| Cause code | C (content), P (process), T (time), X (named slip), G (guess-right) |\n| The exact moment it went wrong | \"Chose B after eliminating A and C; did not test D against the goal\" |\n| The trap, if any | \"True-but-irrelevant data\" or \"discriminant of wrong equation\" |\n| Rule sentence | One sentence for next time |\n| Time spent | Find your time sinks |\n\n**Slow-correct questions are hidden misses.** If a question took three minutes, it stole time from two others. Log it."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":6}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '7')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Step 3: Choosing targets by trap, not by domain$sat_pb$, 7, $sat_pb${"markdown":"Domain-level targets (\"work on Advanced Math\") are too broad here. Choose **two traps or habits** per cycle, for example:\n\n- \"Cross-text partial agreement\" and \"SPR decimal precision\".\n- \"Rhetorical synthesis two-part goals\" and \"parameter questions with no-solution conditions\".\n\nUse the trap families in [R&W Hard-Module Traps](/guide-rw-hard-module-traps) and [Math Hard-Module Traps](/guide-math-hard-module-traps) as a menu. Your forensic review tells you which two to pick."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":7}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '8')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Step 4: Hard-only drilling$sat_pb$, 8, $sat_pb${"markdown":"- In the [SAT Practice Bank](https://practice.sat.schood.online/bank), filter to **hard** in the target skills. Medium questions no longer teach you much.\n- **Set size:** 10–15 questions, timed at test pace, then full review.\n- **Mix sets** after the first few days: interleave the target skill with other hard skills so you practise *recognising* the trap, not just solving it when you know it is coming.\n- **Re-solve after 48 hours** every miss and every slow question, with no notes.\n\n**Accuracy target for the drill phase:** aim to make your misses in the target skill rare across 30 hard questions. If misses persist, go back one step: untimed, with a written method, then time it again."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":8}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '9')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Step 5: The zero-careless protocol$sat_pb$, 9, $sat_pb${"markdown":"\"Be more careful\" is not a method. These are:\n\n**Math**\n- **Circle the ask.** Before computing, underline what the question wants (k? 2k? the sum of solutions?).\n- **Sign sweep.** On every equation you write, re-read the signs once before solving.\n- **SPR entry check.** Before leaving a question, compare the box with your work: sign, fraction bar, number of decimal places. The Bluebook directions allow 5 characters for positive answers and 6 for negative ones, and decimals that don't fit are truncated or rounded at the fourth digit, so fill the box when you convert.\n- **Units and form.** Percent versus decimal, minutes versus hours, radius versus diameter.\n\n**Reading and Writing**\n- **Task restatement.** Say the task in three words before reading choices.\n- **Negative-word alert.** Mark NOT, EXCEPT, LEAST and \"weaken\" when they appear.\n- **Final-choice test.** Before confirming, ask: \"Does every part of this choice fit the passage and the task?\"\n- **Pair check in boundaries.** If a supplementary element opens with a comma or dash, confirm it closes with the same mark.\n\n**Track it.** Count X codes per mock. The protocol is working when X codes approach zero across two mocks in a row."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":9}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '10')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Step 6: Time control in the upper modules$sat_pb$, 10, $sat_pb${"markdown":"**Reading and Writing (32 minutes, 27 questions).**\n- Conventions and transitions should be your fastest items. Aim for under 45 seconds each.\n- Keep a time bank of a few minutes for cross-text, data and inference items near the end of skill groups.\n- Use mark for review, not stubbornness: two minutes and still split between two choices means choose, mark and move on.\n\n**Math (35 minutes, 22 questions).**\n- First 8 questions: brisk, but verify.\n- Questions 9–16: invest where needed, using Desmos routines from [Desmos Power Moves](/guide-desmos-power-moves).\n- Questions 17–22: read the final sentence first; expect parameter, circle and statistics combinations.\n- Reserve the last 3–4 minutes for flagged items and an SPR re-read.\n\n**Remember:** when the module timer reaches zero, Bluebook moves you on automatically, and you cannot return to a module once you have left it."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":10}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '11')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Step 7: Reducing variance$sat_pb$, 11, $sat_pb${"markdown":"Write down the score of every mock. After three, look at the spread.\n\n- **Wide spread, high best score:** your problem is reliability. Prioritise the zero-careless protocol, sleep before mocks, consistent timing and identical test-day routines.\n- **Narrow spread, plateau:** your problem is a ceiling. Prioritise new trap families and harder sets.\n- **Drop on one section only:** check whether that section's misses cluster at the end (fatigue or time) or throughout (content).\n\nPractise your **break routine** in every mock: water, a small snack, a short walk if allowed, and no reviewing of the section you just finished."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":11}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '12')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$A forensic review, worked through$sat_pb$, 12, $sat_pb${"markdown":"Two illustrative misses from a 1450-level mock, reviewed with the full protocol.\n\n**Miss 1: Reading and Writing, cross-text.** The question asked how the author of Text 2 would respond to Text 1. The student chose an answer saying Text 2 *rejects* Text 1's claim entirely.\n\n- **Re-solve before the explanation:** on a second read, the student notices Text 2 begins by accepting Text 1's evidence and only disputes its conclusion. Re-solved correctly.\n- **Cause code:** P (process). The student knew how to do these questions but read Text 2 for its disagreement only.\n- **Trap:** partial agreement.\n- **Rule sentence:** *\"Before choosing, write one word for what Text 2 accepts and one for what it rejects.\"*\n- **Time spent:** about 2 minutes, which also makes it a slow question.\n\n**Miss 2: Math, student-produced response.** The answer was −5/6, and the student entered −.83.\n\n- **Re-solve:** the algebra was correct; the entry was not. The Bluebook directions allow 6 characters for a negative answer, so −.8333 fitted and −.83 lost precision.\n- **Cause code:** X (named slip: \"shortened a decimal\").\n- **Trap:** SPR precision.\n- **Rule sentence:** *\"When I convert to a decimal, I fill the box.\"*\n\n**What the review produced:** two targets for the next cycle (partial-agreement cross-text items and SPR precision), each with a concrete habit. Neither required learning new content, which is common at this level."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":12}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '13')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Building hard-only sets that teach$sat_pb$, 13, $sat_pb${"markdown":"Random hard sets are better than medium sets, but designed sets are better still.\n\n- **Block, then interleave.** Spend the first two days of a cycle on blocked sets (all one trap family), so you can learn the pattern. From day three, interleave: mix the target family with three or four other hard skills, so you practise *recognising* the trap without being told it is coming.\n- **Decoy writing.** On every multiple-choice item in a set, write a five-word reason for rejecting each wrong choice. It is slow at first and is one of the most direct ways to stop falling for near-miss answers.\n- **Speed tier.** Once accuracy is high, rerun similar sets at a slightly faster pace than test pace. This creates a time cushion for test day.\n- **Cold start.** At least once a week, begin a session with a hard timed set before any warm-up. The first questions of the real test are not preceded by a warm-up set either."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":13}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '14')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Stamina and full-test conditions$sat_pb$, 14, $sat_pb${"markdown":"The test is 2 hours 14 minutes of testing plus a 10-minute break, and the second module of each section comes at the end of that section. Fatigue can cost the last points even when the knowledge is there.\n\n- **Run full mocks at your test time of day,** in one sitting.\n- **Practise the break** exactly as you will take it: drink, snack, a short stand or walk, no thinking about the R&W section.\n- **Read dense nonfiction daily** so that the last R&W questions do not feel heavier than the first.\n- **Notice end-of-module drift.** If your forensic review shows misses clustering in the last five questions of a module, add one extra timed module per week and practise the final-minute routine (SPR re-read, flagged items) until it is automatic."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":14}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '15')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Using your real score report$sat_pb$, 15, $sat_pb${"markdown":"After an official test, the score report's Knowledge and Skills section shows performance in the four R&W and four Math content areas. Use it as a cross-check, not as your only diagnosis:\n\n- If a content area shows lower performance than the others and your mock reviews agree, it is a real target.\n- If the score report and your mock reviews disagree, trust the pattern across several mocks, which contain far more of your answers than a single test.\n- If you plan another attempt, read [Retake and Superscore Strategy](/retake-and-superscore-strategy) before booking."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":15}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '16')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Weekly targets$sat_pb$, 16, $sat_pb${"markdown":"| Target | Each week |\n|---|---|\n| Study hours | 8–12, in 5–6 sessions |\n| Hard-only questions | 80–120, all reviewed |\n| Re-solves | Every logged item from the previous week, after 48 hours |\n| Timed upper-level modules | At least one per section |\n| Error-log codes | X codes trending down; T codes trending down |\n| Reading | 20–30 minutes daily of dense nonfiction |\n\n**Weekly checkpoint (15 minutes):** count entries by trap family and cause code, and write the two targets for the following week."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":16}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '17')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$The Reading and Writing plan above 700$sat_pb$, 17, $sat_pb${"markdown":"- **Dense passages.** Practise slowing down on the *one* sentence that carries the claim, finding or contrast, rather than slowing down on the whole passage.\n- **Two-part goals in rhetorical synthesis.** Count goal verbs; require all of them.\n- **Cross-text.** Name what Text 2 accepts and rejects before reading choices.\n- **Quantitative evidence.** Translate the claim into the comparison it needs (difference, trend, ratio) before looking at the table.\n- **Words in context.** Use punctuation and contrast words as the definition; avoid choices that are merely possible.\n- **Conventions mastery.** At this level conventions should be near-perfect. Any remaining miss becomes an immediate rule sentence and a 20-question drill."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":17}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '18')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$The Math plan above 700$sat_pb$, 18, $sat_pb${"markdown":"- **Parameters everywhere.** No-solution and infinitely-many conditions; discriminant tangency; vertex and root relationships.\n- **Structure over computation.** Sum and product of roots, equivalent forms, factoring by substitution.\n- **Modelling interpretation.** What a coefficient, base or intercept means in context; percent change per different period.\n- **Geometry and trigonometry edges.** Radians, arc length, scaled volumes, complementary angles, circle equations with completed squares.\n- **Statistics claims.** Random sampling versus random assignment; margin of error as a plausible range.\n- **Desmos fluency.** Sliders, regressions with constraints and list statistics should be second nature."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":18}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '19')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Advanced Math drill: structure before computation$sat_pb$, 19, $sat_pb${"markdown":"Top scorers save time by spotting structure. Two original examples:\n\n**Example 1 (student-produced response).** If x² + y² = 29 and xy = 10, what is the value of (x + y)²?\n\nExpand: (x + y)² = x² + 2xy + y² = 29 + 2(10) = **49**. Solving for x and y separately would work (x and y are 2 and 5) but wastes time, and on harder versions the individual values are not integers.\n\n**Example 2 (student-produced response).** The expression (2x + 7)/(x + 2) can be rewritten as a + b/(x + 2), where a and b are constants. What is a + b?\n\nRewrite the numerator around the denominator: 2x + 7 = 2(x + 2) + 3. So the expression equals 2 + 3/(x + 2), giving a = 2, b = 3 and **a + b = 5**. Desmos check: graph the original and `y = 2 + 3/(x + 2)`; they coincide.\n\n**The habit:** before computing, ask \"is there an identity or rearrangement that gives the requested quantity directly?\" The requested quantity is often a combination (x + y, a + b, 1/r + 1/s) precisely because a structural route exists."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":19}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '20')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Advanced R&W drill: decoy writing in practice$sat_pb$, 20, $sat_pb${"markdown":"Decoy writing means writing a short reason against every wrong choice. On a quantitative-evidence item like the roof-coating example in [R&W Hard-Module Traps](/guide-rw-hard-module-traps), a finished decoy sheet looks like this:\n\n| Choice | Five-word verdict |\n|---|---|\n| A | True; compares wrong quantity |\n| B | Shows differing reductions: key |\n| C | True; ignores the coating |\n| D | Shows equal benefit: opposite |\n\n**Why it works.** Most misses at this level are not caused by failing to see the right answer; they are caused by failing to *reject* a near-miss. Writing the verdict forces you to name the flaw, and the flaws repeat: wrong quantity, wrong scope, half the goal, too extreme, true but off-task. After two or three weeks, you start seeing the verdicts before you write them.\n\n**How often.** Use decoy writing on every item in the first two days of each cycle, then on any item you hesitate over."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":20}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '21')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$The endgame of each section$sat_pb$, 21, $sat_pb${"markdown":"**Reading and Writing.** If your last misses are spread across many skills, the issue is usually reading precision under time; add the claim-first habit and a daily dense-reading session. If they cluster in one skill, drill that skill with blocked then interleaved sets for one cycle.\n\n**Math.** If your last misses are in the final third of the second module, the issue is usually time or setup on long items; practise reading the final sentence first and choosing a route (algebra, Desmos, or structure) within the first few seconds. If they are scattered SPR entry errors, the zero-careless protocol is the fix, not more content."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":21}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '22')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$What to stop doing at this level$sat_pb$, 22, $sat_pb${"markdown":"- **Stop doing medium sets for comfort.** They feel productive and hide your real gaps.\n- **Stop reviewing only wrong answers.** Slow and guessed answers are where your next points are.\n- **Stop broad content review.** Re-reading whole chapters you already know wastes the hours you need for traps.\n- **Stop chasing obscure topics.** If a topic is not in the official domain and skill lists, it is not on the test.\n- **Stop taking mocks back to back.** A mock without a full forensic review day is a lost data point.\n- **Stop judging yourself on one mock.** Use the trend of three.\n- **Stop studying late the night before mocks.** Rehearse the real test-eve routine instead."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":22}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '23')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$What to start doing at this level$sat_pb$, 23, $sat_pb${"markdown":"- **Teach-back:** after each forensic review, explain your two worst misses out loud as if to a student. If you cannot explain the trap, you have not learned it.\n- **Decoy practice:** for hard multiple-choice questions, write down why *each* wrong choice is wrong, not just why the key is right.\n- **Retake planning:** if you will test more than once, read [Retake and Superscore Strategy](/retake-and-superscore-strategy). The College Board notes that many colleges consider your highest section scores across test dates, but policies vary, so check each college."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":23}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '24')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$A sample eight-week sequence$sat_pb$, 24, $sat_pb${"markdown":"| Week | Primary target | Secondary target | Test |\n|---|---|---|---|\n| 1 | Forensic review baseline | Zero-careless protocol | Mock 1 (day 1) |\n| 2 | R&W: data and weaken/strengthen | Math: parameters | Timed upper modules |\n| 3 | R&W: cross-text | Math: nonlinear systems | Mock 2 |\n| 4 | R&W: rhetorical synthesis | Math: SPR precision | Timed upper modules |\n| 5 | R&W: words in context (hard) | Math: geometry and trig edges | Mock 3 |\n| 6 | Variance review | Time control | Timed upper modules |\n| 7 | Weakest remaining trap family | Desmos speed | Mock 4 |\n| 8 | Final mixed hard sets | Test-day rehearsal | Mock 5, then taper |\n\nFor the last two weeks before a real test, switch to the [Final 14 Days](/guide-final-14-days) schedule. A ready-made day-by-day plan for this stage is the [Four-Week Sprint](/plans/four-week-sprint) if you already have a test date close by."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":24}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '25')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$checklist$sat_pb$, $sat_pb$Checkpoints$sat_pb$, 25, $sat_pb${"items":["Three consecutive full mocks within a narrow band near your target.","X (named slip) codes rare across the last two mocks.","No question took more than about three minutes in the last two mocks.","Every trap family in both hard-module guides attempted and logged.","All re-solves from the last two weeks correct.","Break and test-eve routines rehearsed at least twice."]}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":25}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '26')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Frequently asked questions$sat_pb$, 26, $sat_pb${"markdown":"**Should I keep doing full mocks every week?** One per two-week cycle is usually enough, plus timed modules. At this level the forensic review is where improvement happens, and it takes a full day.\n\n**My Math is 790 but R&W is 720. Should I still study Math?** Yes, briefly: two short hard-only sessions a week keep it sharp. Put the rest into R&W, which has more reachable points.\n\n**I keep missing one or two hard Math questions per test. Is that just bad luck?** Usually not. Log them by trap family. If they come from different families each time, broaden your hard-only drills; if from the same family, drill that family until it is boring.\n\n**How do I know I am ready to test?** When your last three mocks are in a tight band at or near your target, and your error log shows no repeated trap family."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":26}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$ || ':' || '27')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-1400-to-1550-roadmap$sat_pb$)::uuid, $sat_pb$callout$sat_pb$, $sat_pb$Summary$sat_pb$, 27, $sat_pb${"label":"The method in one line","body":"At this level you are not learning the SAT; you are removing the few ways you still lose points. Review forensically, drill only hard questions in two trap families per cycle, run the zero-careless protocol every time, and judge progress by the trend of three mocks."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":27}$sat_pb$::jsonb)
) as v(id, page_id, block_type, heading, sort_order, content, metadata)
where exists (select 1 from public.sat_playbook_pages p where p.id = v.page_id)
on conflict do nothing;

-- Sections: guide-desmos-power-moves (24 sections, 3114 words)
insert into public.sat_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select v.id, v.page_id, v.block_type, v.heading, 'published', v.sort_order, v.content, v.metadata
from (
  values
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '1')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Who this guide is for$sat_pb$, 1, $sat_pb${"markdown":"The public module [Desmos and Calculator Strategy](/desmos-and-calculator-strategy) covers the basics: where the calculator lives in Bluebook, graphing a function, reading intercepts. This premium guide assumes you can do all of that and teaches **routines**: short, repeatable sequences of keystrokes that solve whole families of SAT questions, and the decision rules that tell you when a routine beats algebra and when it does not.\n\n**Verified context.** According to the College Board calculator policy, Bluebook includes an embedded Desmos calculator with graphing and scientific modes, and a calculator may be used throughout the Math section (the Reading and Writing section does not allow one). You may bring an approved handheld calculator instead, but the routines here are Desmos-specific.\n\n**Practise in the right place.** Use the Desmos calculator inside Bluebook's official practice tests at least a few times, so that the layout you train on matches the one you see on test day. If any feature behaves differently there, follow what Bluebook shows."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":1}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '2')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$The core principle: let the graph answer "how many" and "which"$sat_pb$, 2, $sat_pb${"markdown":"Algebra is excellent at producing an exact value. Graphs are excellent at answering *how many*, *where* and *which one*. The highest-value Desmos questions on the SAT are therefore:\n\n- **Counting solutions** of systems and equations.\n- **Finding a parameter** that changes the number of solutions.\n- **Choosing an equivalent expression** from four options.\n- **Reading features** (vertex, intercepts, maximum) of a model.\n- **Summarising data** (mean, median, spread) without hand arithmetic.\n\n**Decision rule:** if the question asks for a count, a feature or a comparison, open Desmos first. If it asks for an exact value you can reach in two lines of algebra, do the algebra and use Desmos only to check."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":2}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '3')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Setup habits that save seconds$sat_pb$, 3, $sat_pb${"markdown":"- **One question, one clean screen.** Delete old expressions before starting a new question; leftover graphs cause misreads.\n- **Zoom to fit.** If a graph is not visible, zoom out or use the zoom-fit control rather than guessing the window.\n- **Click points, do not estimate.** Desmos marks intercepts, intersections and turning points as grey dots when you click a curve. Clicking shows exact coordinates (to displayed precision).\n- **Use the scientific mode for long arithmetic** only if switching is faster for you; the graphing mode evaluates numbers too.\n- **Check angle mode** in the calculator settings before evaluating trigonometric expressions. SAT questions use both degrees and radians."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":3}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '4')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Move 1: Solve any equation by graphing both sides$sat_pb$, 4, $sat_pb${"markdown":"**Routine.**\n1. Type the left side as `y = 3(x - 2) + 5`.\n2. Type the right side as `y = 2x + 9`.\n3. Click the intersection. The x-coordinate is the solution.\n\nHere the lines meet at x = 10, so the equation 3(x − 2) + 5 = 2x + 9 has solution x = 10.\n\n**Why two sides instead of one.** Graphing both sides works for every type of equation (linear, quadratic, exponential, absolute value, radical), and it shows the *number* of solutions at a glance. Many equations in one variable can also be typed directly and Desmos draws vertical lines at the solutions, but the two-sided method is the one that never surprises you.\n\n**Watch out:** for radical and rational equations, the graph shows only real intersections, which automatically removes extraneous solutions that algebra might produce. If your algebra gives two answers and Desmos shows one intersection, trust the graph and recheck the algebra."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":4}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '5')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Move 2: Systems of equations, including nonlinear ones$sat_pb$, 5, $sat_pb${"markdown":"**Routine.**\n1. Enter each equation on its own line, exactly as written (Desmos accepts forms like `2x + 3y = 12`; you do not need to solve for y).\n2. Click each intersection point to read its coordinates.\n3. Count intersections when the question asks how many solutions exist.\n\n**Example.** For y = x² − 4x + 1 and y = x − 3, Desmos shows two intersections, at (1, −2) and (4, 1). Algebra confirms: x² − 5x + 4 = 0 gives x = 1 or x = 4.\n\n**Upper-module variant.** \"If (a, b) is a solution to the system and a > 2, what is b?\" Click both intersections, choose the one with x-coordinate greater than 2, read b = 1."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":5}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '6')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Move 3: Sliders for parameter questions$sat_pb$, 6, $sat_pb${"markdown":"Parameter questions (\"for what value of k...\") are where Desmos gives the biggest advantage to students who know this routine.\n\n**Routine.**\n1. Type the equation with the parameter as a letter, for example `y = x^2 + bx + 9`.\n2. Desmos offers to add a slider for b. Accept it.\n3. Drag the slider and watch the graph. Note the value where the behaviour changes (for example, where the parabola stops crossing the x-axis and just touches it).\n4. Narrow the slider range or type values directly to land on the exact value.\n5. **Confirm with algebra** (here, discriminant b² − 36 = 0 gives b = 6 for b > 0).\n\n**Why confirm.** A slider shows you the neighbourhood of the answer; algebra pins it exactly. Together they take less time than either alone on a hard question, and the slider protects you from setting up the wrong equation.\n\n**Slider settings.** Click the slider's limits to change the range and step. For SAT questions, a range of −20 to 20 with step 0.5 or 1 usually finds the neighbourhood quickly."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":6}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '7')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Move 4: "No solution" and "infinitely many solutions" with sliders$sat_pb$, 7, $sat_pb${"markdown":"**Routine for linear systems.**\n1. Enter `3x + ay = 7` and `6x - 4y = 5`, accepting a slider for a.\n2. Drag a until the lines look parallel (no intersection).\n3. Confirm with coefficient ratios: 3/6 must equal a/(−4), so a = −2. The constants are not in the same ratio, so the lines are distinct and the system has no solution.\n\nIf the lines ever lie exactly on top of each other, the system has infinitely many solutions; that only happens when the constants also share the ratio."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":7}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '8')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Move 5: Inequalities and test points$sat_pb$, 8, $sat_pb${"markdown":"**Routine.**\n1. Enter each inequality: `y > 2x - 3` and `y <= -x + 6`. Desmos shades each region; the overlap is the solution set. Use `<=` or `>=` for \"or equal to\".\n2. To test a candidate point from the answer choices, type it as a point, for example `(1, 4)`.\n3. A point inside the doubly shaded region satisfies both inequalities.\n\n**Example.** The point (1, 4) satisfies both: 4 > −1 and 4 ≤ 5. The point (3, 2) fails the first inequality, because 2 is not greater than 3. Dashed boundary lines mean the boundary is excluded; solid lines mean it is included.\n\n**Upper-module variant.** \"Which point is a solution to the system?\" Type all four answer points at once; only one lands in the overlap."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":8}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '9')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Move 6: Restrictions with curly brackets$sat_pb$, 9, $sat_pb${"markdown":"Desmos lets you restrict where a graph is drawn by adding conditions in curly brackets at the end of an expression.\n\n- `y = 2x {0 < x < 3}` draws the line only for x between 0 and 3.\n- `y = x^2 - 4 {x >= 0}` draws only the right half of the parabola.\n\n**SAT uses.**\n- Modelling questions with a stated domain (\"for 0 ≤ t ≤ 10\").\n- Piecewise reasoning, by graphing each piece with its own restriction.\n- Removing clutter: restrict a curve so only the relevant intersection remains."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":9}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '10')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Move 7: Equivalent expressions by overlay$sat_pb$, 10, $sat_pb${"markdown":"**Routine.**\n1. Graph the original expression, for example `y = (x^2 - 9)/(x - 3)`.\n2. Graph each answer choice on its own line.\n3. The equivalent choice draws directly on top of the original. Toggle graphs on and off (click the coloured circle) to see which coincides.\n\n**Caution: holes.** (x² − 9)/(x − 3) and x + 3 look identical on the graph, but the first is undefined at x = 3. If a question asks about values where an expression is *defined*, the overlay alone is not enough; check the restrictions algebraically.\n\n**Speed tip.** Instead of graphing, test with a number. Defining x itself as a number would change every graph on the screen, so use a different letter: define `t = 2.7`, then type the original expression and each choice with t in place of x and compare the values. Pick an unusual test value (not 0, 1 or 2), because special values can make non-equivalent expressions agree by coincidence."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":10}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '11')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Move 8: Reading features of quadratics and other models$sat_pb$, 11, $sat_pb${"markdown":"**Routine.**\n1. Graph the function.\n2. Click the curve. Desmos shows the turning point (vertex), the x-intercepts and the y-intercept as grey dots.\n3. Click each dot for coordinates.\n\n**Uses.** Maximum height of a projectile model, minimum cost, break-even points, and \"which equation has a graph with vertex (h, k)\" questions, where you graph each choice and click.\n\n**Define and evaluate functions.** Type `f(x) = 3x^2 - 2` and `g(x) = 2x + 1`, then type `f(g(2))`. Desmos returns 73. This removes composition errors entirely."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":11}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '12')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Move 9: Linear regression from a table$sat_pb$, 12, $sat_pb${"markdown":"Some data questions give a table and ask for the line of best fit, a predicted value or the meaning of a slope.\n\n**Routine.**\n1. Add a table (from the add-item menu) and enter the x-values in the first column and y-values in the second. Desmos names the columns x₁ and y₁.\n2. On a new line, type `y1 ~ m x1 + b`. Desmos shows the 1s as subscripts; if your keyboard does not convert them, type `y_1 ~ m x_1 + b`.\n3. Desmos reports the fitted values of m and b and a measure of fit (r²).\n\n**Example data:** x = 1, 2, 3, 4, 5 and y = 3.1, 4.9, 7.2, 8.8, 11.1. The fit gives m = 1.99, b = 1.05 and r² about 0.997. A predicted value at x = 8 is 1.99 × 8 + 1.05 = 16.97.\n\n**Interpretation questions.** The slope is the predicted change in y for each one-unit increase in x; the intercept is the predicted y when x = 0 (which may be outside the data and meaningless in context)."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":12}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '13')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Move 10: Regressions with constraints$sat_pb$, 13, $sat_pb${"markdown":"The tilde (~) fits any model you write, and you can constrain the model in two ways.\n\n**Constraint by form.** Leave out a term you know is zero. If a question says a quantity is proportional to another, fit `y1 ~ m x1` (a line through the origin). On the data above, this gives m about 2.28, a different slope from the unconstrained fit, which is exactly why form matters.\n\n**Constraint by range.** The Desmos help documentation shows parameter restrictions written in curly brackets after the model, such as `y1 ~ a x1^b {1 < b < 5}`. The calculator then searches only within that range. Use this when context rules out values (a decay factor must be between 0 and 1; a growth rate must be positive).\n\n**Exponential example.** Data (0, 200), (1, 180), (2, 162), (3, 145.8). Fit `y1 ~ a b^x1 {0 < b < 1}`. Desmos returns a = 200 and b = 0.9, so the model is y = 200(0.9)ˣ: an initial value of 200 decreasing by 10% per step.\n\n**Exact fit from three points.** A quadratic `y1 ~ a x1^2 + b x1 + c` fitted to exactly three points passes through all of them. For (0, 5), (1, 2) and (3, 2) it gives a = 1, b = −4, c = 5: the parabola y = x² − 4x + 5 with vertex (2, 1). This answers \"which equation passes through these points\" in seconds."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":13}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '14')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Move 11: List statistics$sat_pb$, 14, $sat_pb${"markdown":"**Routine.**\n1. Create a list with square brackets: `L = [12, 15, 15, 18, 20, 22, 26]`.\n2. Type `mean(L)`, `median(L)`, `min(L)`, `max(L)` on separate lines.\n3. For spread, `stdev(L)` gives the sample standard deviation and `stdevp(L)` the population standard deviation.\n\nFor this list: mean ≈ 18.29, median 18.\n\n**Compare two data sets.** Replace 26 with 60 in a second list, `M = [12, 15, 15, 18, 20, 22, 60]`. The median stays 18, the mean rises to about 23.14 and the sample standard deviation jumps from about 4.79 to about 16.60. This is the classic SAT outlier question, answered by typing rather than reasoning from slogans.\n\n**Frequency tables.** For values V = [1, 2, 3, 4] with frequencies F = [3, 5, 8, 4], the mean is `total(V F)/total(F)` (Desmos multiplies lists element by element), which gives 53/20 = 2.65. For the median, use cumulative counts: there are 20 values, the 10th and 11th both fall in the group with value 3, so the median is 3.\n\n**SAT note.** Most SAT spread questions ask you to *compare* standard deviations, not compute them. Desmos lets you confirm a comparison in seconds when the data are given numerically."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":14}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '15')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Move 12: Circles and other implicit equations$sat_pb$, 15, $sat_pb${"markdown":"Desmos graphs equations in x and y without solving for y.\n\n**Routine.**\n1. Type the circle exactly as given, for example `x^2 + y^2 - 8x + 6y - 11 = 0`.\n2. Click the leftmost, rightmost, top and bottom points. The centre is midway between opposite points; the radius is half the distance across.\n3. For intersections with a line, add the line and click the intersections.\n\n**Example.** The circle (x − 4)² + (y + 3)² = 36 and the line y = x − 1 meet at (4, 3) and (−2, −3). Both points satisfy the circle equation.\n\n**Still learn the algebra.** \"What is the radius?\" is faster by completing the square once you are fluent, and some questions give the circle in a form with parameters, where Desmos needs sliders."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":15}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '16')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Move 13: Checking student-produced responses$sat_pb$, 16, $sat_pb${"markdown":"Desmos is an excellent final check for SPR answers.\n\n- **Convert fractions:** type `7/12` to see 0.58333... Then apply the Bluebook entry rules: up to 5 characters for a positive answer, 6 for a negative answer, with long decimals truncated or rounded at the fourth digit.\n- **Substitute back:** define `t = -7/12` and type the original equation's left side with t; confirm it equals the right side.\n- **Catch sign errors:** graph both sides and confirm the intersection's x-coordinate has the sign you entered."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":16}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '17')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Move 14: Maximum, minimum and "for what value" questions in context$sat_pb$, 17, $sat_pb${"markdown":"Many modelling questions ask when a quantity is largest or smallest, or when it reaches a given value.\n\n**Routine.**\n1. Graph the model with the variable names changed to x and y, for example `y = -4.9x^2 + 19.6x + 2` for a height model.\n2. Click the curve to find the maximum point: here (2, 21.6), so the maximum height is 21.6 when x = 2.\n3. For \"when does the height equal 10?\", add `y = 10` and click the intersections.\n4. Restrict to the meaningful domain with curly brackets, for example `{x >= 0}`, so you do not report a negative time.\n\n**Interpretation check.** Always translate the coordinates back into the question's words: x was time, y was height. Many wrong answers come from reporting the wrong coordinate of the right point."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":17}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '18')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Worked example: one hard question, three routes$sat_pb$, 18, $sat_pb${"markdown":"**Question (original).** The function g is defined by g(x) = x² − 10x + c, where c is a constant. If the minimum value of g is −7, what is g(2)?\n\n**Route A: algebra.** Completing the square, g(x) = (x − 5)² + (c − 25). The minimum is c − 25 = −7, so c = 18. Then g(2) = 4 − 20 + 18 = **2**.\n\n**Route B: slider.** Type `g(x) = x^2 - 10x + c`, accept the slider for c, click the vertex and drag c until the vertex reads (5, −7). The slider stops at c = 18. Type `g(2)` and read 2.\n\n**Route C: vertex shortcut plus Desmos check.** The vertex of x² − 10x + c is at x = 5 (half of 10). So g(5) = 25 − 50 + c = −7 gives c = 18. Type `g(2)` with c = 18 to confirm.\n\n**Which route is best?** For a student fluent in completing the square, Route A or C takes under a minute. Route B is a safe fallback when the algebra looks messy. The real skill is choosing in the first five seconds."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":18}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '19')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$When not to use Desmos$sat_pb$, 19, $sat_pb${"markdown":"Desmos costs time to type. Skip it when:\n\n- The equation is linear and short (two steps of algebra are faster than typing).\n- The question asks for an expression in terms of other variables (\"solve for h in terms of V and r\").\n- The question is about **interpreting** a model (what does 0.9 represent?), where no graph helps.\n- The arithmetic is simple and typing risks a transcription error.\n\n**The 30-second rule:** if you can write a correct algebraic solution in about 30 seconds, do it, then use Desmos only if time remains to check."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":19}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '20')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Common Desmos errors and fixes$sat_pb$, 20, $sat_pb${"markdown":"| Error | Symptom | Fix |\n|---|---|---|\n| Fraction captures too much | Typing `1/2x` puts 2x in the denominator | Press the right arrow after the 2 to leave the fraction, or type `(1/2)x` |\n| Wrong angle mode | Trig values look strange | Check degrees/radians in settings |\n| Leftover expressions | Extra intersections | Clear the screen per question |\n| Window too small | \"No intersection\" | Zoom out or zoom-fit |\n| Defining x as a number | Other graphs disappear or change | Use a different letter (t, u) |\n| Estimating instead of clicking | Off-by-a-little answers | Click points for coordinates |"}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":20}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '21')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$A practice routine for building speed$sat_pb$, 21, $sat_pb${"markdown":"Typing fluency matters as much as knowing the moves.\n\n- **Week 1:** 10 minutes a day running Moves 1–4 on Algebra and Advanced Math items from the [SAT Practice Bank](https://practice.sat.schood.online/bank). Time each question and write whether Desmos or algebra was faster.\n- **Week 2:** Moves 5–8 on mixed medium and hard items.\n- **Week 3:** Moves 9–12 on data and geometry items in Problem-Solving and Data Analysis and Geometry and Trigonometry.\n- **Week 4:** full 22-question timed Math modules, deciding *before each question* whether to open Desmos. Review the decisions afterwards.\n\nThen test under real conditions in a full mock in the [SAT simulator](https://sat.schood.online)."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":21}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '22')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$checklist$sat_pb$, $sat_pb$Self-check$sat_pb$, 22, $sat_pb${"items":["I can solve any single-variable equation by graphing both sides.","I can find and count intersections of linear and nonlinear systems.","I use sliders to locate a parameter value and confirm it with algebra.","I can shade a system of inequalities and test answer-choice points.","I can restrict a graph's domain with curly brackets.","I can test equivalent expressions by overlay and know the hole caveat.","I can fit linear, exponential and quadratic models with the tilde.","I can constrain a regression by form and by parameter range.","I can compute mean, median and standard deviation from a list.","I know when typing into Desmos is slower than algebra."]}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":22}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '23')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Where to go next$sat_pb$, 23, $sat_pb${"markdown":"- Apply these moves to the traps in [Math Hard-Module Traps](/guide-math-hard-module-traps).\n- Revisit [Math: Problem-Solving and Data Analysis](/math-problem-solving-data-analysis) for the statistics concepts behind Move 11.\n- For pacing, see [Pacing and Adaptive Modules](/pacing-and-adaptive-modules)."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":23}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-desmos-power-moves$sat_pb$ || ':' || '24')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-desmos-power-moves$sat_pb$)::uuid, $sat_pb$callout$sat_pb$, $sat_pb$Independent tool notice$sat_pb$, 24, $sat_pb${"label":"About Desmos","body":"Desmos is a third-party calculator embedded in Bluebook by the College Board. Schood is not affiliated with Desmos or the College Board. Feature descriptions here follow Desmos's public help pages; the version in Bluebook is what counts on test day."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":24}$sat_pb$::jsonb)
) as v(id, page_id, block_type, heading, sort_order, content, metadata)
where exists (select 1 from public.sat_playbook_pages p where p.id = v.page_id)
on conflict do nothing;

-- Sections: guide-final-14-days (34 sections, 3134 words)
insert into public.sat_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select v.id, v.page_id, v.block_type, v.heading, 'published', v.sort_order, v.content, v.metadata
from (
  values
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '1')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$What the last two weeks are for$sat_pb$, 1, $sat_pb${"markdown":"Two weeks is not enough time to learn new areas of the test, and that is not the goal. The final 14 days have three jobs:\n\n1. **Rehearse** the exact test experience until it feels routine.\n2. **Remove** the most frequent remaining error types, using what your last mocks show.\n3. **Protect** your energy, sleep and logistics so that nothing outside the questions costs you points.\n\nThis guide gives a day-by-day schedule built around **three full practice tests**, a **forensic review protocol**, and **test-eve and test-day routines**. It assumes you have already worked through most of the public modules; if you have not, the [Test-Day Guide](/test-day-guide) and [Pacing and Adaptive Modules](/pacing-and-adaptive-modules) are the first reads."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":1}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '2')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Verified facts that shape the schedule$sat_pb$, 2, $sat_pb${"markdown":"From official College Board pages (see the sources panel):\n\n- The test is **two sections**: Reading and Writing (two 32-minute modules) and Math (two 35-minute modules), **2 hours 14 minutes** of testing with a **10-minute break** between sections.\n- Within a module you can move freely, mark questions for review and use the question menu; **when the timer reaches zero you move on, and you cannot return to a module after leaving it.**\n- The testing timer can be hidden, and an alert appears when **5 minutes** remain.\n- You need your **fully charged testing device** with **Bluebook installed and exam setup completed**, your **admission ticket** (printed copy preferred), and a **physical photo ID**. Bring pencils or pens for scratch work.\n- Your admission ticket becomes available **5 days before the test**, after exam setup.\n- A calculator is permitted throughout Math; Bluebook includes a built-in Desmos graphing and scientific calculator, and approved handheld calculators may be used."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":2}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '3')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$The shape of the 14 days$sat_pb$, 3, $sat_pb${"markdown":"| Day | Main task | Load |\n|---|---|---|\n| 14 | Full practice test 1 | Heavy |\n| 13 | Forensic review of test 1 | Medium |\n| 12 | Targeted fix: R&W trap family | Medium |\n| 11 | Targeted fix: Math trap family + timed modules | Medium |\n| 10 | Full practice test 2 | Heavy |\n| 9 | Forensic review of test 2 | Medium |\n| 8 | Targeted fix + logistics check | Medium |\n| 7 | Full practice test 3 (final full test) | Heavy |\n| 6 | Review of test 3; build your rule sheet | Medium |\n| 5 | Exam setup and admission ticket; one timed module per section | Light |\n| 4 | Mixed short sets; re-solves | Light |\n| 3 | Rules and Desmos refresh; route planning | Light |\n| 2 | Short warm-up sets; pack your bag | Very light |\n| 1 | Test eve: rest routine | Rest |\n| 0 | Test day | Test |\n\n**Days are counted backwards to the test.** If your test is on a Saturday, Day 14 is the Saturday two weeks before."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":3}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '4')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Choosing your three practice tests$sat_pb$, 4, $sat_pb${"markdown":"- **Test 1 and Test 3:** official full-length Bluebook practice tests you have not taken before. They show the real interface and the official question style.\n- **Test 2:** a full mock in the [Schood SAT simulator](https://sat.schood.online), so that you see fresh material and a different question pool.\n- If you have already used all the official tests, use the simulator for all three, and spend more of the review on *process* than on content.\n- **Do not** use tests you have taken before as score estimates; familiar questions inflate scores."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":4}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '5')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Rules for every full practice test$sat_pb$, 5, $sat_pb${"markdown":"- Start at the **same time of day as your real test**.\n- Use the **device you will test on**, plugged in or fully charged.\n- **One sitting,** with only the 10-minute break between sections.\n- **No phone,** no music, no pausing, no checking answers.\n- Use scratch paper and pencils as on test day.\n- Mark every guess and every question where you hesitated between two choices.\n- Eat the same breakfast and break snack you plan for test day."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":5}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '6')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$How the review protocol fits into two hours$sat_pb$, 6, $sat_pb${"markdown":"Reviews in the final two weeks must be thorough but must not eat the whole day. A timed plan for a full-test review:\n\n- **0–10 min:** list every missed, guessed and slow question, by module.\n- **10–60 min:** re-solve them untimed, without explanations. Mark the ones you now get right.\n- **60–90 min:** read explanations for the rest; assign cause codes; name traps.\n- **90–110 min:** write rule sentences, one per entry.\n- **110–120 min:** count codes and choose the next two fix targets.\n\n**Rule:** if you run out of time, skip the questions that were *right but slow* before skipping wrong ones."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":6}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '7')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Day 14: Full practice test 1$sat_pb$, 7, $sat_pb${"markdown":"**Task.** Take Test 1 under the rules above.\n\n**After the test (20 minutes, no more).** Write down three things: how your energy felt in each module, where time felt short, and which questions you remember as hard. Do not start the full review today; you are tired and the review will be shallow."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":7}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '8')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Day 13: Forensic review of test 1$sat_pb$, 8, $sat_pb${"markdown":"Use this protocol for every review in the next two weeks.\n\n**The forensic review protocol (2–3 hours):**\n1. **List** every missed, guessed and slow question (Math over about two minutes; R&W over about 90 seconds).\n2. **Re-solve** each one *before* reading the explanation, untimed. Note whether you could get it right with time.\n3. **Read the explanation** and assign one cause code: C (content), P (process), T (time), X (named slip), G (guess-right).\n4. **Name the trap** where one exists, using the trap families in [R&W Hard-Module Traps](/guide-rw-hard-module-traps) and [Math Hard-Module Traps](/guide-math-hard-module-traps).\n5. **Write a rule sentence** for each item.\n6. **Count** codes and traps. The two most frequent become your fix targets for Days 12 and 11.\n\nLog everything in the [SAT Practice notebook](https://practice.sat.schood.online/notebook)."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":8}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '9')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Day 12: Targeted fix (Reading and Writing)$sat_pb$, 9, $sat_pb${"markdown":"- **20 minutes:** reread the guide section for your top R&W trap family.\n- **40 minutes:** 15–20 hard questions in that skill from the [SAT Practice Bank](https://practice.sat.schood.online/bank), timed at about 70 seconds each.\n- **20 minutes:** review; add rule sentences.\n- **15 minutes:** clear [Reviews](https://practice.sat.schood.online/reviews).\n- **15 minutes:** Math maintenance, 8 mixed medium-hard questions."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":9}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '10')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Day 11: Targeted fix (Math) and timed modules$sat_pb$, 10, $sat_pb${"markdown":"- **40 minutes:** 15–20 hard questions in your top Math trap family. Use the matching move from [Desmos Power Moves](/guide-desmos-power-moves).\n- **20 minutes:** review.\n- **Evening, 70 minutes:** one timed R&W module (27 questions, 32 minutes) and one timed Math module (22 questions, 35 minutes) in SAT Practice. Count misses in your two target areas only."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":10}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '11')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Day 10: Full practice test 2$sat_pb$, 11, $sat_pb${"markdown":"Take **Test 2 (simulator mock)** under full rules. Afterwards, write the same 20-minute note as on Day 14, plus one extra line: *did the target errors from test 1 appear again?*"}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":11}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '12')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Day 9: Forensic review of test 2$sat_pb$, 12, $sat_pb${"markdown":"Run the full protocol. Then compare the two tests:\n\n- **Codes that appeared in both tests** are your real patterns. These become the fix targets for Day 8.\n- **Codes that appeared once** may be noise; note them but do not chase them.\n- **Section that dropped:** check whether the misses cluster at the end of modules (time or fatigue) or are spread out (content or process)."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":12}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '13')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Day 8: Targeted fix and logistics check$sat_pb$, 13, $sat_pb${"markdown":"**Practice (90 minutes):** two short hard-only sets (15 questions each) on the repeated patterns from Day 9, with full review.\n\n**Logistics (30 minutes):**\n- Check your test-day device meets the device requirements, and that Bluebook is updated.\n- Check your **photo ID** is valid and physical.\n- If you plan to use a handheld calculator, confirm it is an approved, non-CAS model and replace its batteries. Remember that Bluebook's Desmos calculator is always available in Math.\n- Confirm your test centre address and plan the journey."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":13}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '14')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Day 7: Full practice test 3$sat_pb$, 14, $sat_pb${"markdown":"Your **final full test**. Take it exactly as you will take the real one, from wake-up time to breakfast to break snack. This is a dress rehearsal as much as a score check.\n\n**Important:** whatever the score, do not change your plan dramatically now. Use it to choose the final rule sheet, not to start new topics."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":14}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '15')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Day 6: Review test 3 and build your rule sheet$sat_pb$, 15, $sat_pb${"markdown":"- Run the forensic protocol, but cap it at two hours.\n- **Build a one-page rule sheet:** your ten most useful rule sentences from all three reviews, written by hand. Examples: \"Count goal verbs in rhetorical synthesis.\" \"Fill the SPR box when converting to a decimal.\" \"Write the combined equation before using the discriminant.\"\n- You will read this sheet once a day until the test."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":15}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '16')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Writing a rule sheet that works$sat_pb$, 16, $sat_pb${"markdown":"A good rule sheet is short, personal and written as instructions to yourself.\n\n**Good rules** are specific actions tied to a question type:\n- \"Rhetorical synthesis: count the goal verbs; the answer must do all of them.\"\n- \"Cross-text: say what Text 2 accepts before what it rejects.\"\n- \"Systems with a parameter: compare coefficient ratios, then constants.\"\n- \"Percent changes: multiply, never add.\"\n- \"SPR: fill the box when converting to a decimal; check the sign.\"\n\n**Weak rules** are general wishes: \"be careful\", \"read slowly\", \"focus\". If a rule does not tell you what to *do* on a particular kind of question, rewrite it or remove it.\n\n**Ten is the limit.** You will read the sheet once a day for five days. With more than ten rules, few of them stick."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":16}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '17')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Day 5: Exam setup and admission ticket$sat_pb$, 17, $sat_pb${"markdown":"- **Exam setup:** the College Board says your admission ticket becomes available 5 days before the test, after exam setup in Bluebook. Complete exam setup on your testing device, signing in with your College Board account.\n- **Admission ticket:** print it (a printed copy is preferred) and also email it to yourself.\n- **Practice (70 minutes):** one timed module per section. Treat them as rhythm practice: smooth pacing, calm review at the end.\n- **Read your rule sheet.**"}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":17}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '18')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Day 4: Mixed short sets and re-solves$sat_pb$, 18, $sat_pb${"markdown":"- **45 minutes:** re-solve every logged question from the last ten days, without notes.\n- **30 minutes:** a mixed set of 12 R&W and 10 Math questions at medium and hard difficulty.\n- **Read your rule sheet.**\n- **Sleep:** start going to bed at the time you need for test-day wake-up, if you have not already."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":18}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '19')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Day 3: Rules and Desmos refresh$sat_pb$, 19, $sat_pb${"markdown":"- **R&W (30 minutes):** boundaries rules, agreement and modifier rules, transition relationships; 15 quick conventions questions.\n- **Math (30 minutes):** formulas you use often; the reference sheet available in Bluebook; the five Desmos moves you rely on most, rehearsed once each.\n- **Route:** check your travel time to the test centre and plan to leave with a margin. Check your admission ticket for the arrival time and centre details."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":19}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '20')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Day 2: Light warm-up and pack your bag$sat_pb$, 20, $sat_pb${"markdown":"- **20 minutes:** 6 R&W and 6 Math questions you are likely to get right. The goal is confidence and rhythm, not learning.\n- **Pack your bag tonight** using the checklist below. Charge your device fully.\n- **Read your rule sheet** one last time and put it away."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":20}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '21')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$checklist$sat_pb$, $sat_pb$Bag checklist$sat_pb$, 21, $sat_pb${"items":["Testing device, fully charged, with Bluebook installed and exam setup completed","Admission ticket (printed copy preferred)","Physical photo ID","Pencils or pens for scratch work","Approved calculator, if you are bringing one (optional; Desmos is built in)","Charging cable or portable charger (optional; an outlet is not guaranteed)","A drink and a snack for the break","A watch without an audible alarm (optional; Bluebook has a timer)","Your College Board username and password"]}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":21}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '22')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Day 1: The test-eve routine$sat_pb$, 22, $sat_pb${"markdown":"**What to do**\n- A short walk, light exercise, or anything that relaxes you.\n- A normal dinner, nothing new or heavy.\n- Lay out clothes in layers (rooms can be cold or warm).\n- Set two alarms.\n- Go to bed at your planned time.\n\n**What not to do**\n- No new practice questions. At most, 10 minutes of looking at your rule sheet in the afternoon.\n- No full tests, no score predictions, no comparing with friends.\n- No late screens; your device is already charged and packed.\n\n**If you cannot sleep.** Rest with the lights off and do not get up to study. The sleep routine you built over the previous nights is what you are relying on."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":22}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '23')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Managing nerves in the final fortnight$sat_pb$, 23, $sat_pb${"markdown":"Nerves often grow as the date approaches. Practical steps that keep them manageable:\n\n- **Rehearsal is the main tool.** Three full tests under real conditions make test day feel familiar. That familiarity is the point of the schedule.\n- **Keep the routine boring.** Same wake time, same breakfast, same break snack in every full test and on test day.\n- **Limit score-checking.** Look at a mock score once, then work from the review, not from the number.\n- **Write worries down.** If a worry keeps returning (\"what if my device fails?\"), write the plan for it (raise your hand, tell the proctor) and put it away.\n- **Move every day.** A short walk on review days is an easy reset."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":23}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '24')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Testing away from home$sat_pb$, 24, $sat_pb${"markdown":"If your test centre is in another city or country:\n\n- **Arrive the day before** if travel is long, and keep Day 1 as the test eve wherever you are.\n- **Find the centre location** the evening before if you can, so the morning route is known.\n- **Pack the bag before travelling,** and keep the device, ticket and ID in your hand luggage.\n- **Check local time** against the arrival time on your admission ticket."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":24}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '25')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Test-day morning routine$sat_pb$, 25, $sat_pb${"markdown":"- Wake at your rehearsed time; eat your rehearsed breakfast.\n- **Warm-up (10 minutes):** two easy R&W questions and two easy Math questions you have seen before, solved calmly. This switches your brain into test mode without stress.\n- Leave with a margin for travel. Check your bag: device, ticket, ID.\n- At the centre, follow the proctor's instructions on phones and other devices."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":25}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '26')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$During the test: module-by-module routine$sat_pb$, 26, $sat_pb${"markdown":"**Reading and Writing, module 1.** Settle in on the first few questions; they are among the easier ones in each skill group. Do not rush them; module 1 performance determines your second module.\n\n**Reading and Writing, module 2.** If it feels harder, that is the design, not a sign of failure. Keep the claim-first habit, bank time on conventions, mark and move when stuck.\n\n**The 10-minute break.** Drink, eat your snack, stand up. Do **not** replay R&W questions in your head. Read nothing about the test. Return before the break ends.\n\n**Math, module 1.** Brisk and accurate. Re-read every SPR entry before moving on.\n\n**Math, module 2.** Read the last sentence of long questions first. Use your Desmos moves. Reserve the last few minutes for flagged items.\n\n**Throughout:** answer every question. The College Board's assessment framework says there is no guessing penalty and recommends answering every question as well as you can; a blank cannot earn credit."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":26}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '27')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$If something goes wrong$sat_pb$, 27, $sat_pb${"markdown":"- **A question you cannot solve:** choose your best answer, mark it, move on. One question is never worth three.\n- **Panic:** stop for ten seconds, breathe out slowly, read the question's last sentence again. Then work the first step you can see.\n- **Device trouble:** raise your hand and tell the proctor immediately. Do not try to fix it alone.\n- **Calculator failure:** use Bluebook's Desmos calculator, which is available throughout Math.\n- **A module feels terrible:** how a module feels is not a reliable guide to your score, especially in a harder second module, which is meant to be challenging. Leave it behind at the module boundary."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":27}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '28')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$After the test$sat_pb$, 28, $sat_pb${"markdown":"- Rest. Do not rework questions from memory; you cannot change anything now.\n- Check your College Board account for score information when it is released.\n- When scores arrive, read the Knowledge and Skills section of the score report before deciding anything.\n- If you plan to retake, read [Retake and Superscore Strategy](/retake-and-superscore-strategy) and choose the matching Schood plan."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":28}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '29')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Adjusting the schedule$sat_pb$, 29, $sat_pb${"markdown":"- **Only 10 days left?** Drop test 2 and Day 9; keep tests 1 and 3, both reviews and the final five days.\n- **Only 7 days left?** One full test on Day 7, review on Day 6, then follow Days 5–1 as written.\n- **Test on a school day?** Keep the full tests on weekends and move fix days to weekday evenings (60 minutes each).\n- **Very anxious?** Keep all three tests, as repetition is the strongest anxiety treatment, but shorten fix days to 60 minutes and add a daily walk."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":29}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '30')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$If a mock score drops in the final week$sat_pb$, 30, $sat_pb${"markdown":"A lower score on test 3 than on test 2 is unsettling, but it is not a reason to change course. Scores vary between tests; College Board score reports include a score range alongside each score to show how much a score would likely vary on another test under identical conditions. Before reacting, check the review:\n\n- **Did the misses come from new trap families?** If so, add them to your rule sheet and do one short targeted set on Day 4.\n- **Did they come from fatigue or time?** If the misses cluster at the end of modules, check your sleep, breakfast and break routine on that day. Fix the routine, not the content.\n- **Did they come from slips?** If X codes rose, run the zero-careless protocol in the remaining timed modules.\n- **Was the test harder or unfamiliar?** Different practice tests vary. Judge by the trend of all three tests, not the last one alone.\n\n**What not to do:** add an extra full test in the last four days, start a new topic, or study late. Each of those makes the real test more tiring without making you more prepared."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":30}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '31')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$A sample day plan for school weeks$sat_pb$, 31, $sat_pb${"markdown":"If you are at school during the final fortnight, fit the schedule around lessons. A typical weekday on a fix day:\n\n| Time | Task | Minutes |\n|---|---|---|\n| Before school | Read your rule sheet (from Day 6 onward) | 5 |\n| After school | Targeted hard set in SAT Practice | 40 |\n| Short break | Snack, walk, no screens | 15 |\n| Early evening | Review the set; rule sentences | 25 |\n| Evening | Clear due Reviews | 10 |\n| Bedtime | Same time every night | – |\n\n**Weekends** carry the full practice tests and the long reviews. If a full test must move to a weekday, take it on a day with no school, or swap it with the following fix day."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":31}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '32')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Food, water and comfort on test day$sat_pb$, 32, $sat_pb${"markdown":"Keep everything familiar:\n\n- **Breakfast** you have eaten before every full practice test, not something new.\n- **Water and a light snack** for the break, as allowed by the testing rules.\n- **Layers of clothing** so you can adjust to the room.\n- **A watch without an audible alarm** if you like to see time without the on-screen timer (optional; Bluebook has its own timer)."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":32}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '33')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$checklist$sat_pb$, $sat_pb$Final checklist$sat_pb$, 33, $sat_pb${"items":["Three full practice tests taken under real conditions, each reviewed forensically","Rule sheet of ten personal rules written by hand","Exam setup completed and admission ticket printed","Device charged and meeting requirements; Bluebook updated","Physical photo ID checked","Calculator approved with fresh batteries, or the decision to use Desmos only","Route and arrival plan confirmed","Bag packed the night before","Sleep schedule aligned with test-day wake-up for at least four nights"]}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":33}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-final-14-days$sat_pb$ || ':' || '34')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-final-14-days$sat_pb$)::uuid, $sat_pb$callout$sat_pb$, $sat_pb$Summary$sat_pb$, 34, $sat_pb${"label":"The two-week rule","body":"Rehearse, remove, protect. Three full tests, three forensic reviews, a handwritten rule sheet, and no new material in the last 48 hours."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":34}$sat_pb$::jsonb)
) as v(id, page_id, block_type, heading, sort_order, content, metadata)
where exists (select 1 from public.sat_playbook_pages p where p.id = v.page_id)
on conflict do nothing;

-- Sections: guide-math-hard-module-traps (24 sections, 3811 words)
insert into public.sat_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select v.id, v.page_id, v.block_type, v.heading, 'published', v.sort_order, v.content, v.metadata
from (
  values
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '1')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Who this guide is for$sat_pb$, 1, $sat_pb${"markdown":"This guide is for students whose first Math module is already strong enough to route them to the **harder second module** most of the time, and who now lose points in a narrow band of question types. If you still miss easy and medium linear-equation questions, go back to the public module [Math: Algebra](/math-algebra) first; the habits below assume those basics are automatic.\n\nWhat changes in the upper module is not the content list. The College Board describes the second module of each section as targeted to your performance in the first one, either harder or easier on average. The same four domains appear, but the questions combine two ideas at once, hide the real question behind an extra step, or reward a student who knows *which* tool to use. This guide teaches those combinations, the specific traps they set, and the fastest reliable route through each one.\n\n**How to use it:** read one block per study session, then do the matching drill set in [SAT Practice](https://practice.sat.schood.online/bank) filtered to *hard* difficulty in that skill. Log every miss in your notebook using the error codes in the final sections."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":1}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '2')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$What the official specification tells you about the hard module$sat_pb$, 2, $sat_pb${"markdown":"Verified facts from the College Board pages listed in the sources panel:\n\n- The Math section has **two modules of 22 questions each**, **35 minutes per module**, 44 questions and 70 minutes in total.\n- The first module contains a mix of easy, medium and hard questions; your performance on it determines whether the second module is harder or easier.\n- Questions come from four domains: **Algebra** and **Advanced Math** (about 35% each, 13–15 questions), and **Problem-Solving and Data Analysis** and **Geometry and Trigonometry** (about 15% each, 5–7 questions).\n- Roughly **25%** of Math questions are **student-produced response** (SPR): you type your own answer.\n- About **30%** of Math questions are set in context.\n- A calculator is permitted for **every** Math question, and a reference sheet is available throughout.\n\n**Consequence for strategy:** Algebra and Advanced Math together make up around 70% of the section, so the hard module is mostly algebra and nonlinear reasoning dressed in harder clothing. A student aiming at 750+ cannot afford a weak spot in parameters, systems or quadratics, because those are the questions that appear again and again."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":2}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '3')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$The five ways an upper-module question becomes hard$sat_pb$, 3, $sat_pb${"markdown":"Before the items, learn the patterns. Almost every hard question uses at least one of these:\n\n1. **Two-step disguise.** The question asks for something you only get after finding something else (for example, asks for k after you find a discriminant condition).\n2. **Parameter instead of number.** A letter such as *a*, *b*, *c* or *k* replaces a constant, and the question asks for the value that produces a special outcome (no solution, one solution, infinitely many).\n3. **Form over value.** The answer is an expression or an equivalent form, and three choices are \"almost\" equivalent.\n4. **Interpretation.** You must say what a number in a model *means* (a rate, an initial value, a percent change per period).\n5. **Entry precision.** The answer is correct but can be entered wrongly in an SPR box.\n\n**Decision rule:** when you read a hard question, first name which of the five patterns it uses. Naming the pattern tells you the method before you start calculating."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":3}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '4')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 1: Nonlinear systems and the "exactly one solution" condition$sat_pb$, 4, $sat_pb${"markdown":"**Worked item 1 (multiple choice).** The graphs of y = x² − 6x + k and y = 2x − 3 intersect at exactly one point in the xy-plane. What is the value of k?\n\n- A) 6\n- B) 9\n- C) 13\n- D) 16\n\n**Solution.** Set the expressions equal: x² − 6x + k = 2x − 3. Move everything to one side: x² − 8x + (k + 3) = 0. Exactly one intersection means this quadratic has exactly one real solution, so the discriminant is zero: 64 − 4(k + 3) = 0, so k + 3 = 16 and **k = 13 (C)**. Check: with k = 13 the equation becomes (x − 4)² = 0, the single intersection is at x = 4, and both graphs give y = 5.\n\n**Why the wrong choices are tempting.**\n- **A (6)** comes from forgetting to move the 2x term: x² − 6x + (k + 3) = 0 gives 36 − 4(k + 3) = 0 and k = 6. This is a classic upper-module setup error: setting the discriminant of the *wrong* quadratic.\n- **D (16)** is k + 3, the value of the constant term, mistaken for k.\n- **B (9)** is the square of half of 6, the number students reach for when they think \"complete the square\" without setting up the combined equation.\n\n**Desmos route.** Graph both equations, type k as a slider, and drag until the line just touches the parabola. Then confirm algebraically; a slider gives you the neighbourhood, the discriminant gives you the exact value."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":4}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '5')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 2: Linear systems with a parameter$sat_pb$, 5, $sat_pb${"markdown":"**Worked item 2 (multiple choice).** In the system 3x + ay = 7 and 6x − 4y = 5, a is a constant. For which value of a does the system have no solution?\n\n- A) −4\n- B) −2\n- C) 2\n- D) −8\n\n**Solution.** A linear system has no solution when the lines are parallel and distinct: the coefficients of x and y are proportional, but the constants are not. Compare 3 : 6 with a : (−4). The ratio 3/6 = 1/2, so a/(−4) must also be 1/2, giving **a = −2 (B)**. Check the constants: multiplying the first equation by 2 gives 6x − 4y = 14, which is not 6x − 4y = 5, so the lines are parallel and distinct. No solution confirmed.\n\n**Why the wrong choices are tempting.**\n- **C (2)** is a sign slip: students compare a with 4 instead of −4.\n- **A (−4)** copies the y-coefficient of the second equation without scaling.\n- **D (−8)** inverts the ratio: setting a/(−4) equal to 6/3 instead of 3/6.\n\n**The three outcomes in one table.**\n\n| Situation | Coefficient ratio | Constant ratio | Graph |\n|---|---|---|---|\n| Exactly one solution | Not proportional | Any | Lines cross once |\n| No solution | Proportional | Not the same ratio | Parallel, distinct |\n| Infinitely many | Proportional | Same ratio | Same line |"}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":5}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '6')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 3: Sums and products of roots$sat_pb$, 6, $sat_pb${"markdown":"**Worked item 3 (student-produced response).** The equation 2x² − 10x + 8 = 0 has two real solutions, r and s. What is the value of r² + s²?\n\n**Solution.** You could solve directly: dividing by 2 gives x² − 5x + 4 = 0, so (x − 1)(x − 4) = 0 and the solutions are 1 and 4. Then r² + s² = 1 + 16 = **17**.\n\nThe faster structural route, useful when the roots are ugly: for ax² + bx + c = 0, r + s = −b/a and rs = c/a. Here r + s = 5 and rs = 4. Since (r + s)² = r² + 2rs + s², you get r² + s² = 25 − 8 = 17.\n\n**Traps.** Entering **25** (you squared the sum and stopped) or **33** (you added 2rs instead of subtracting). Both are numbers you actually computed on the way, which is exactly why they feel right.\n\n**When the structural route matters.** If a hard question gives 3x² − 7x + 1 = 0 and asks for 1/r + 1/s, solving with the quadratic formula wastes a minute. Instead, 1/r + 1/s = (r + s)/(rs) = (7/3)/(1/3) = 7."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":6}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '7')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 4: Vertex and roots linked by a parameter$sat_pb$, 7, $sat_pb${"markdown":"**Worked item 4 (student-produced response).** The function f is defined by f(x) = (x − 3)(x + k), where k is a constant. The graph of y = f(x) has its vertex at x = 5. What is the value of k?\n\n**Solution.** The x-coordinate of a parabola's vertex is the midpoint of its x-intercepts. The intercepts are x = 3 and x = −k. Their midpoint is (3 + (−k))/2 = 5, so 3 − k = 10 and **k = −7**. Check: f(x) = (x − 3)(x − 7) has intercepts 3 and 7, midpoint 5.\n\n**Trap.** Entering **7**: students take the second intercept (7) and report it as k, forgetting the factor is (x + k). In an SPR box, the minus sign is the whole question. Enter **-7**."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":7}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '8')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 5: Equations with infinitely many solutions$sat_pb$, 8, $sat_pb${"markdown":"**Worked item 5 (student-produced response).** In the equation 4(2x − c) = 8x − 12, c is a constant. If the equation has infinitely many solutions, what is the value of c?\n\n**Solution.** Expand: 8x − 4c = 8x − 12. The x-terms already match, so the equation is an identity exactly when −4c = −12, giving **c = 3**.\n\n**Upper-module twist to expect.** The same idea appears with a *no solution* condition (\"for which value of c does the equation have no solution?\"), where the answer becomes \"any value except 3\", which is why such questions are usually multiple choice. Read which condition the question asks for before you compute."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":8}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '9')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 6: Exponential growth rate per different period$sat_pb$, 9, $sat_pb${"markdown":"**Worked item 6 (multiple choice).** A population of bacteria doubles every 6 hours. Which of the following is closest to the percent increase in the population each hour?\n\n- A) 2%\n- B) 12%\n- C) 17%\n- D) 33%\n\n**Solution.** If P(t) = P₀ · 2^(t/6), the hourly growth factor is 2^(1/6) ≈ 1.1225, an increase of about 12.25% per hour. **Answer: B.**\n\n**Why the wrong choices are tempting.**\n- **D (33%)** divides the growth factor 2 by 6 hours (2/6 ≈ 0.33) and reads the result as a percent.\n- **C (17%)** spreads 100% growth evenly over 6 hours (100%/6 ≈ 16.7%). Growth compounds, so splitting it linearly overestimates the hourly rate.\n- **A (2%)** is the base of the exponent read as a percentage.\n\n**Desmos check.** Type 2^(1/6) and read the value. Then type 1.1225^6 to confirm it is close to 2."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":9}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '10')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 7: Successive percent changes$sat_pb$, 10, $sat_pb${"markdown":"**Worked item 7 (student-produced response).** The price of an item was increased by 25%. The new price was then decreased by p%, and the final price was 10% less than the original price. What is the value of p?\n\n**Solution.** Use multipliers: 1.25 × (1 − p/100) = 0.90. So 1 − p/100 = 0.72 and **p = 28**.\n\n**Trap.** Entering **35**: the reasoning \"up 25, net down 10, so down 35\" adds percentages as if they applied to the same base. Percent changes in sequence multiply; they never add. This trap can appear at any difficulty; harder versions tend to hide it inside longer contexts (discounts, population, depreciation)."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":10}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '11')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 8: Circles in the coordinate plane$sat_pb$, 11, $sat_pb${"markdown":"**Worked item 8 (multiple choice).** The equation x² + y² − 8x + 6y − 11 = 0 defines a circle in the xy-plane. What is the radius of the circle?\n\n- A) √11\n- B) 6\n- C) 11\n- D) 36\n\n**Solution.** Complete the square in x and in y: (x² − 8x + 16) + (y² + 6y + 9) = 11 + 16 + 9, so (x − 4)² + (y + 3)² = 36. The centre is (4, −3) and the radius is **6 (B)**.\n\n**Why the wrong choices are tempting.**\n- **D (36)** is r², a classic circle error.\n- **A (√11)** takes the constant before completing the square.\n- **C (11)** is the moved constant itself.\n\n**Follow-up trap.** A second question on the same circle might ask for the greatest possible y-coordinate of a point on the circle. That is the centre's y-coordinate plus the radius: −3 + 6 = 3. Students who wrote the centre as (−4, 3), flipping signs, answer 9.\n\n**Desmos route.** The graphing calculator graphs the equation exactly as given. Click the top and side of the circle to read extreme points; the centre is midway between opposite extremes."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":11}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '12')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 9: Right-triangle trigonometry and complementary angles$sat_pb$, 12, $sat_pb${"markdown":"**Worked item 9 (student-produced response).** In triangle ABC, angle C is a right angle and sin A = 0.6. What is the value of tan B?\n\n**Solution.** sin A = opposite/hypotenuse = 3/5, so the leg opposite A is 3, the hypotenuse is 5, and the remaining leg (opposite B) is 4. Then tan B = (side opposite B)/(side adjacent to B) = 4/3. **Enter 4/3** (or 1.333).\n\n**Trap.** Entering **3/4**, which is tan A. Upper-module trigonometry questions often ask about the *other* acute angle. Draw the triangle and label each side relative to the angle the question names, every time.\n\n**Related identity worth knowing.** In a right triangle, sin A = cos B because A and B are complementary. A hard question might give sin(x°) = cos(40°) and ask for x; the answer is 50 when both angles are acute."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":12}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '13')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 10: Radians and arc length$sat_pb$, 13, $sat_pb${"markdown":"**Worked item 10 (multiple choice).** On a circle with radius 6, an arc has length 5π. What is the measure, in radians, of the central angle that intercepts this arc?\n\n- A) 5π/12\n- B) 5π/6\n- C) 150\n- D) 30π\n\n**Solution.** Arc length s = rθ when θ is in radians, so θ = 5π/6. **Answer: B.**\n\n**Traps.** **D** multiplies the arc length by the radius instead of dividing. **A** divides by the diameter (12) instead of the radius. **C** is the correct angle in *degrees*, offered to students who forget the question asks for radians. If you prefer degrees, the arc is 5π/(12π) = 5/12 of the circumference, which is 150°, and 150° = 5π/6 radians."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":13}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '14')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 11: Scaling area and volume$sat_pb$, 14, $sat_pb${"markdown":"**Worked item 11 (multiple choice).** Cylinder P has radius r and height h. Cylinder Q has radius 1.5r and height 0.8h. The volume of cylinder Q is what percent of the volume of cylinder P?\n\n- A) 120%\n- B) 150%\n- C) 180%\n- D) 225%\n\n**Solution.** Volume is πr²h, so the scale factor is 1.5² × 0.8 = 2.25 × 0.8 = 1.8. **Answer: C (180%).**\n\n**Traps.** **A** forgets to square the radius factor (1.5 × 0.8). **D** squares the radius but ignores the height change. **B** uses only the radius factor. Rule: lengths scale by k, areas by k², volumes by k³, and when dimensions scale *differently*, multiply each factor raised to the power it appears with in the formula."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":14}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '15')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 12: Mean, median and outliers$sat_pb$, 15, $sat_pb${"markdown":"**Worked item 12 (multiple choice).** A data set consists of the values 3, 5, 5, 6, 8, 9, 10, 12 and 40. If the value 40 is removed, which statement is true?\n\n- A) The mean and the median both decrease, and the mean decreases by more.\n- B) The mean and the median both decrease, and the median decreases by more.\n- C) The mean decreases and the median stays the same.\n- D) The median decreases and the mean stays the same.\n\n**Solution.** With all nine values the sum is 98, so the mean is about 10.89 and the median (5th value) is 8. Without 40, the sum is 58 across 8 values, so the mean is 7.25 and the median is the average of 6 and 8, which is 7. The mean falls by about 3.64 and the median by 1. **Answer: A.**\n\n**Trap.** **C** is the intuition \"the median ignores outliers\". It resists outliers, but removing a value changes the *count*, and the middle position moves. In upper-module data questions, recompute the median position rather than relying on slogans."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":15}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '16')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 13: Evaluating statistical claims$sat_pb$, 16, $sat_pb${"markdown":"**Worked item 13 (multiple choice).** A researcher selected 400 adults at random from the residents of a city and asked whether they supported a new bike lane. Of those surveyed, 62% said yes. The margin of error for this estimate is 4.9 percentage points. Which conclusion is best supported?\n\n- A) Exactly 62% of the city's adults support the bike lane.\n- B) It is plausible that between 57.1% and 66.9% of the city's adults support the bike lane.\n- C) Between 57.1% and 66.9% of adults in every city in the region support a bike lane.\n- D) The bike lane will reduce traffic accidents in the city.\n\n**Solution.** A random sample supports an estimate for the population it was drawn from, with the margin of error giving a range of plausible values: 62 − 4.9 = 57.1 and 62 + 4.9 = 66.9. **Answer: B.**\n\n**Why the others fail.** **A** ignores sampling variability. **C** generalises beyond the sampled population. **D** claims a causal effect that a survey of opinions cannot establish.\n\n**Claim-checking checklist for every statistics question:**\n- Was the sample **random**? Without random selection you cannot generalise to the population.\n- **Which population** was sampled? Conclusions stop at that population.\n- Was there **random assignment** to treatments? Only then can you conclude cause and effect.\n- Is the answer stated as a **range or plausibility**, not a certainty?"}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":16}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '17')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 14: Student-produced response entry pitfalls$sat_pb$, 17, $sat_pb${"markdown":"**Worked item 14 (student-produced response).** If 2/x + 1/(3x) = −4, what is the value of x?\n\n**Solution.** Combine the fractions: 2/x = 6/(3x), so 6/(3x) + 1/(3x) = 7/(3x). Then 7/(3x) = −4 gives 3x = −7/4 and **x = −7/12**.\n\n**Entering it.** The Bluebook directions allow up to 5 characters for a positive answer and up to 6 (including the negative sign) for a negative answer. A fraction that does not fit must be entered as a decimal, and a decimal that does not fit is truncated or rounded at the fourth digit. Mixed numbers must be entered as improper fractions or decimals, and symbols such as %, $ or commas must be left out.\n\nFor −7/12:\n\n| Entry | Characters | Acceptable? |\n|---|---|---|\n| -7/12 | 5 | Yes (fits) |\n| -.5833 | 6 | Yes |\n| -0.583 | 6 | Yes, uses all available space |\n| -.58 | 4 | No: you had room for more precision |\n| -0.58 | 5 | No: same reason |\n\n**Rule:** when you convert to a decimal, fill the box. Short decimals are marked wrong because they lose precision you were allowed to keep.\n\n**Other SPR traps.**\n- The answer is a **percent** (for example 28%): enter **28**, not 28% and not 0.28, unless the question asks for a decimal.\n- The answer is a **mixed number** like 3½: enter **7/2** or **3.5**, never 3 1/2 (it would read as 31/2).\n- The question has **more than one correct answer**: enter only one."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":17}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '18')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Desmos shortcuts that pay off in the upper module$sat_pb$, 18, $sat_pb${"markdown":"These are covered step by step in [Desmos Power Moves](/guide-desmos-power-moves); here is the quick list for Math-module traps:\n\n- **Systems:** graph both equations and click the intersection. For \"how many solutions\" questions, count intersections, then confirm with algebra if the graphs nearly touch.\n- **Parameters:** type the equation with a letter, accept the slider, and drag. Watch for the moment the number of intersections changes; that is your boundary value.\n- **Quadratics:** click a parabola to see its vertex and x-intercepts as labelled points.\n- **Equivalent forms:** graph the original expression and each answer choice. The equivalent one draws on top of the original.\n- **Data:** put the values into a list (for example L = [3, 5, 5, 6, 8, 9, 10, 12, 40]) and use mean(L) and median(L).\n\n**Decision rule:** if you can write the algebra in under 30 seconds and you trust it, do the algebra. If the question asks *how many* solutions, *which* graph, or involves a messy number, open Desmos first."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":18}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '19')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Pacing inside the hard module$sat_pb$, 19, $sat_pb${"markdown":"Each module gives 35 minutes for 22 questions, a little over a minute and a half per question on average. Questions within a module are arranged from easiest to hardest, so the last third of the hard module holds the heaviest items.\n\nA practical rhythm for 700+ students:\n- **Questions 1–8:** move briskly, but do not skip verification on SPR entries.\n- **Questions 9–16:** spend what each needs; flag anything taking more than about 2.5 minutes.\n- **Questions 17–22:** expect the parameter, circle and statistics combinations above. Read the last sentence first so you know what is being asked.\n- **Final minutes:** return to flagged items, but first re-read every SPR entry you made.\n\nBluebook lets you mark questions for review and move freely within a module, but once the timer runs out you move on and cannot return to that module."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":19}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '20')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Error codes for your notebook$sat_pb$, 20, $sat_pb${"markdown":"Use these codes in the [SAT Practice notebook](https://practice.sat.schood.online/notebook) so patterns become visible:\n\n| Code | Meaning | Fix |\n|---|---|---|\n| WQ | Wrong quadratic / wrong equation set up | Write the combined equation before computing |\n| SG | Sign slip | Circle every negative in the stem |\n| AQ | Answered a different question (e.g. tan A instead of tan B) | Underline the requested quantity |\n| PC | Percent changes added instead of multiplied | Convert every change to a multiplier |\n| R2 | Reported r² as r, or vice versa | Say the formula aloud before answering |\n| EN | Entry error in SPR | Re-read entries in the final two minutes |\n| DS | Should have used Desmos (or should not have) | Apply the 30-second decision rule |"}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":20}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '21')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Fourteen-day drill block for hard-module Math$sat_pb$, 21, $sat_pb${"markdown":"- **Days 1–2:** systems and parameters (items 1, 2, 5). 20 hard Bank items in Advanced Math and Algebra per day, untimed, full write-ups for misses.\n- **Days 3–4:** quadratics, roots and vertex (items 3, 4). Mix structural and Desmos solutions.\n- **Days 5–6:** exponential and percent models (items 6, 7).\n- **Day 7:** one timed 22-question Math module in [SAT Practice](https://practice.sat.schood.online/today), then a full review using the codes above.\n- **Days 8–9:** circles, trigonometry, radians, scaling (items 8–11).\n- **Days 10–11:** statistics and claims (items 12–13).\n- **Day 12:** SPR entry clinic: 15 SPR items where you write the entry before you type it (item 14).\n- **Day 13:** full mock in the [SAT simulator](https://sat.schood.online).\n- **Day 14:** review the mock by error code; the code with the most entries sets your next block."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":21}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '22')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$checklist$sat_pb$, $sat_pb$Self-check before you leave this guide$sat_pb$, 22, $sat_pb${"items":["I set up the combined equation before applying a discriminant condition.","I can state the coefficient and constant conditions for no solution and infinitely many solutions.","I can find r² + s² and 1/r + 1/s from sum and product without solving.","I convert every percent change to a multiplier.","I complete the square on both variables and report r, not r².","I label triangle sides relative to the angle the question names.","I use s = rθ only with radians.","I check whether a sample was random and whether treatments were randomly assigned before choosing a conclusion.","I fill the SPR box when converting to a decimal.","I can name the Desmos move that fits each trap family."]}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":22}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '23')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Where to go next$sat_pb$, 23, $sat_pb${"markdown":"- The public modules [Math: Advanced Math](/math-advanced-math) and [Math: Geometry and Trigonometry](/math-geometry-trigonometry) hold the foundations for every trap family here.\n- [Desmos Power Moves](/guide-desmos-power-moves) turns the shortcuts above into step-by-step routines.\n- If your target is 1400–1550, pair this guide with the [1400 to 1550 Roadmap](/guide-1400-to-1550-roadmap).\n- Drill in [SAT Practice](https://practice.sat.schood.online/bank) with difficulty set to hard, and test the result with a full mock in the [SAT simulator](https://sat.schood.online)."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":23}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-math-hard-module-traps$sat_pb$ || ':' || '24')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-math-hard-module-traps$sat_pb$)::uuid, $sat_pb$callout$sat_pb$, $sat_pb$A note on these items$sat_pb$, 24, $sat_pb${"label":"Original practice","body":"Every worked item in this guide was written by Schood for teaching purposes and checked by calculation. None is copied from official or commercial test material. Use official College Board practice in Bluebook alongside this guide to see the real interface and question style."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":24}$sat_pb$::jsonb)
) as v(id, page_id, block_type, heading, sort_order, content, metadata)
where exists (select 1 from public.sat_playbook_pages p where p.id = v.page_id)
