-- Sections: guide-rw-hard-module-traps (21 sections, 3816 words)
insert into public.sat_playbook_page_sections (id, page_id, block_type, heading, status, sort_order, content, metadata)
select v.id, v.page_id, v.block_type, v.heading, 'published', v.sort_order, v.content, v.metadata
from (
  values
    (md5('schood-sat-pb-section:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$ || ':' || '1')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Who this guide is for$sat_pb$, 1, $sat_pb${"markdown":"This guide is for students who usually reach the **harder second Reading and Writing module** and want the last 50–100 points in the section. You should already be comfortable with the question types covered in the four public R&W modules, starting with [Information and Ideas](/reading-writing-information-ideas) and [Craft and Structure](/reading-writing-craft-structure). Here the focus is narrower: *why* strong readers still miss upper-module questions, and the exact habits that stop those misses.\n\nHard R&W questions rarely use rare vocabulary or long passages. Passages stay short. Difficulty comes from **density** (every clause matters), **precision** (two answers are nearly right) and **task drift** (you answer a slightly different question from the one asked). Each worked item below is original, written to the same specification as the real test, and followed by an explanation of the key and of every distractor."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":1}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$ || ':' || '2')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$What the official specification tells you$sat_pb$, 2, $sat_pb${"markdown":"From the College Board pages in the sources panel:\n\n- Reading and Writing has **two modules of 27 questions each**, **32 minutes per module**: 54 questions in 64 minutes.\n- Every passage is **25–150 words** and is followed by **one** multiple-choice question with **four choices and a single best answer**.\n- Passages cover literature, history/social studies, humanities and science; some come as passage pairs, and some include tables or graphs.\n- Four domains appear in every module: **Craft and Structure** (about 28%), **Information and Ideas** (about 26%), **Standard English Conventions** (about 26%) and **Expression of Ideas** (about 20%).\n- Questions testing similar skills are grouped together and arranged from easiest to hardest within each group.\n- The first module mixes easy, medium and hard questions; your performance on it determines whether the second module is harder or easier.\n\n**What this means.** A hard module still has easier questions at the start of each skill group. Do not slow down on those out of fear; bank them quickly and save time for the last items in each group, which is where upper-module traps live."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":2}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$ || ':' || '3')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Why strong readers still miss upper-module questions$sat_pb$, 3, $sat_pb${"markdown":"Diagnose your misses against these four causes before you read the trap families:\n\n1. **Reading the passage for gist, then choosing an answer that matches the gist.** Hard questions ask about a *specific* relationship (a limitation, a concession, a finding that would weaken a claim), not the topic.\n2. **Accepting a true statement that does not answer the question.** In data and notes questions, three choices are often accurate; only one does the job named in the question.\n3. **Matching words, not meaning.** Distractors reuse vocabulary from the passage in a changed relationship.\n4. **Over-reading.** Choosing an answer that goes beyond what the text supports because it sounds sophisticated.\n\n**The anchor method** (use on every hard question):\n- **Read the question first** and name the task in three words (\"weaken her suggestion\", \"contrast both\", \"support the claim\").\n- **Read the passage once**, marking the sentence that holds the claim, finding or contrast.\n- **Predict** a rough answer before looking at the choices.\n- **Eliminate** by testing each choice against the task, not against the topic."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":3}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$ || ':' || '4')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 1: Dense science passages and "weaken" questions$sat_pb$, 4, $sat_pb${"markdown":"**Worked item 1.**\n\n*Many desert plants open their stomata, the pores through which they exchange gases, only at night, when cooler air reduces water loss. Botanist Lena Okafor wondered whether this nighttime strategy carries a cost in humid years. Comparing two populations of the same cactus species over a decade, she found that the population near a seasonal lake, where humid conditions were common, grew no faster than the population on drier ground, even though humidity should make daytime pore opening less risky. Okafor suggests that the plants' nighttime schedule may be fixed rather than flexible, so that the cacti cannot take advantage of favorable conditions when they arise.*\n\nWhich finding, if true, would most directly weaken Okafor's suggestion?\n\n- A) Cacti in the lake population had more spines than cacti in the dry population.\n- B) In humid years, some cacti in the lake population opened their pores during the day and captured more carbon than they did in dry years.\n- C) The dry-ground population experienced fewer humid periods than the lake population did.\n- D) Other desert plants that open their pores only at night also grow slowly.\n\n**Answer: B.** Okafor's suggestion is that the schedule is *fixed*. Evidence that some plants switched to daytime opening when conditions allowed, and benefited, shows flexibility, which directly undermines the suggestion.\n\n- **A** introduces an unrelated trait; spines say nothing about pore timing.\n- **C** restates part of the study's setup, so it cannot weaken a conclusion drawn from it.\n- **D** is on topic and sounds scientific, but slow growth in other species neither shows nor rules out flexibility in this one.\n\n**Lesson.** For weaken and strengthen questions, write the suggestion as a single claim (\"schedule is fixed\"), then look for the choice that speaks to *that word*."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":4}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$ || ':' || '5')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 2: Quantitative evidence where every choice is true$sat_pb$, 5, $sat_pb${"markdown":"**Worked item 2.**\n\n*A team studying urban heat measured average midafternoon July surface temperatures on four types of roof in one city, with and without a reflective coating. The team claims that the benefit of the coating depends on the roof material rather than being the same for every roof.*\n\n| Roof material | Uncoated (°C) | Coated (°C) |\n|---|---|---|\n| Asphalt shingle | 64 | 41 |\n| Metal | 58 | 44 |\n| Clay tile | 49 | 43 |\n| Concrete | 52 | 38 |\n\nWhich choice most effectively uses data from the table to support the team's claim?\n\n- A) Coated asphalt-shingle roofs were cooler than uncoated roofs of every material.\n- B) The coating lowered asphalt-shingle roof temperatures by 23°C but clay-tile roof temperatures by only 6°C.\n- C) Uncoated metal roofs were hotter than uncoated concrete roofs.\n- D) The coating lowered metal and concrete roof temperatures by the same amount, 14°C.\n\n**Answer: B.** The claim is about the *size of the benefit varying by material*. B compares two reductions (64 − 41 = 23 and 49 − 43 = 6) that differ sharply.\n\n- **A** is true (41 is below 49, 52, 58 and 64) but compares coated with uncoated roofs of different materials; it says nothing about how the benefit varies.\n- **C** is true but ignores the coating entirely.\n- **D** is true and is the most dangerous trap: it uses reductions, as the claim requires, but shows two materials with the *same* benefit, which points away from the claim.\n\n**Lesson.** Before reading the choices, translate the claim into the comparison it needs (\"reduction for material X differs from reduction for material Y\"). Then reject any choice that compares a different quantity, however accurate."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":5}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$ || ':' || '6')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 3: Cross-text connections$sat_pb$, 6, $sat_pb${"markdown":"**Worked item 3.**\n\n*Text 1: Historians have long credited the spread of the printing press in fifteenth-century Europe with a rapid rise in literacy. Because printed books were cheaper than hand-copied manuscripts, the argument runs, more people could afford to own and read them, and reading skills spread accordingly.*\n\n*Text 2: Records of book ownership from several German towns complicate the familiar story. Historian Marta Feld notes that in the decades after printers arrived, most new books were bought by people who already owned manuscripts: clergy, lawyers and wealthy merchants. Cheaper books, in other words, at first deepened existing readers' collections more than they created new readers. Broad gains in literacy, Feld argues, came later and depended on the expansion of schooling.*\n\nBased on the texts, how would Feld most likely respond to the argument presented in Text 1?\n\n- A) By accepting that printing lowered the price of books but disputing that lower prices quickly produced many new readers\n- B) By asserting that printed books were initially more expensive than manuscripts\n- C) By arguing that literacy declined in the decades after the printing press arrived\n- D) By agreeing that the printing press was the main cause of rising literacy in the fifteenth century\n\n**Answer: A.** Feld's phrase \"cheaper books\" accepts the price premise; her objection is to the *speed and mechanism* of the literacy gain.\n\n- **B** contradicts Text 2, which calls printed books cheaper.\n- **C** is too extreme: Feld says new readers came later, not that literacy fell.\n- **D** reverses her position; she credits schooling.\n\n**Lesson.** Most hard cross-text questions reward **partial agreement**. Before choosing, decide: what does Text 2 *accept* from Text 1, and what does it *reject*? The right answer usually names both."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":6}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$ || ':' || '7')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 4: Words in context with a less familiar sense$sat_pb$, 7, $sat_pb${"markdown":"**Worked item 4.**\n\n*Although the committee praised the architect's design for the new library, its endorsement was ______: members approved the reading rooms but asked for the façade to be completely reworked.*\n\nWhich choice completes the text with the most logical and precise word or phrase?\n\n- A) qualified\n- B) unanimous\n- C) fabricated\n- D) premature\n\n**Answer: A.** \"Qualified\" here means *limited by reservations*, which the colon then explains: approval of one part, rejection of another.\n\n- **B** is plausible for a committee in general, but nothing in the sentence concerns whether every member agreed, and \"although\" sets up a limitation, not a vote count.\n- **C** suggests the endorsement was false, which the text never implies.\n- **D** is the strongest trap: an endorsement *could* be premature, but the colon's explanation describes partial approval, not bad timing.\n\n**Lesson.** On hard vocabulary items, the punctuation is the definition. A colon or dash usually explains the blank; \"although\" or \"but\" signals contrast. Use the explanation, not the general mood."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":7}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$ || ':' || '8')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 5: Overall structure$sat_pb$, 8, $sat_pb${"markdown":"**Worked item 5.**\n\n*For decades, ornithologists assumed that the songs of an island's warblers changed little from one generation to the next. Recordings made in 1975 and 2015 at the same sites suggest otherwise: the later songs are shorter and include notes absent from the earlier recordings. Still, the recordings come from only three sites, and the researchers caution that the change might reflect local variation rather than a shift across the whole island.*\n\nWhich choice best describes the overall structure of the text?\n\n- A) It presents a long-held assumption, offers evidence that challenges it, and then notes a limitation of that evidence.\n- B) It describes a scientific debate and explains how the debate was resolved.\n- C) It introduces a hypothesis and presents evidence that confirms it.\n- D) It explains a method of recording birdsong and evaluates its accuracy.\n\n**Answer: A.** Three moves, in order: assumption, challenge (\"suggest otherwise\"), limitation (\"Still... only three sites\").\n\n- **B** fails because the text ends with caution, not resolution.\n- **C** fails because the evidence challenges the assumption and is itself qualified.\n- **D** mistakes a detail (recordings) for the subject.\n\n**Lesson.** Mark the pivot words (*otherwise, still, however, yet*). Each pivot is one structural move; the right answer has the same number of moves in the same order."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":8}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$ || ':' || '9')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 6: Function of a statement in a literary passage$sat_pb$, 9, $sat_pb${"markdown":"**Worked item 6.** *(Original passage written for this guide.)*\n\n*Every morning Mrs. Halloway swept the front step of the shop, though the wind returned the dust within the hour. Her nephew once asked why she bothered. She leaned on the broom and considered the street: the shuttered bakery, the bank that had become a phone store. \"Someone has to show that this door still opens,\" she said.*\n\nWhich choice best describes the function of Mrs. Halloway's final statement in the text as a whole?\n\n- A) It reveals that her sweeping is less about cleanliness than about showing that the shop endures amid changes on the street.\n- B) It shows that she is frustrated with her nephew for questioning her habits.\n- C) It confirms that the wind makes her sweeping pointless.\n- D) It suggests that she plans to close the shop soon.\n\n**Answer: A.** The details she \"considered\" (closed and changed businesses) set up her answer: sweeping is a sign of persistence.\n\n- **B** invents an emotion; nothing shows frustration.\n- **C** echoes the nephew's implied view, not hers.\n- **D** reverses the meaning of \"this door still opens\".\n\n**Lesson.** In literary items, the right answer is supported by *specific details placed just before* the line in question. If a choice requires an emotion or plan the text never shows, eliminate it."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":9}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$ || ':' || '10')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 7: Rhetorical synthesis with a two-part goal$sat_pb$, 10, $sat_pb${"markdown":"**Worked item 7.** While researching a topic, a student has taken the following notes:\n\n- Venus and Mars are Earth's nearest planetary neighbours.\n- Venus has a very thick atmosphere composed mostly of carbon dioxide.\n- Mars also has an atmosphere composed mostly of carbon dioxide.\n- The atmosphere of Mars is very thin.\n\nThe student wants to contrast the two atmospheres while acknowledging what they have in common. Which choice most effectively uses relevant information from the notes to accomplish this goal?\n\n- A) Venus and Mars, Earth's nearest planetary neighbours, both have atmospheres.\n- B) The atmosphere of Venus is very thick, while that of Mars is very thin.\n- C) Although the atmospheres of Venus and Mars are both composed mostly of carbon dioxide, Venus's atmosphere is very thick, while Mars's is very thin.\n- D) Mars has an atmosphere composed mostly of carbon dioxide, and it is very thin.\n\n**Answer: C.** The goal has two parts, *contrast* and *acknowledge common ground*. Only C does both: shared composition, then a difference in thickness.\n\n- **A** states a similarity without a contrast.\n- **B** is the trap for fast readers: a good contrast, but it omits what the atmospheres share.\n- **D** describes one planet only.\n\n**Lesson.** Underline every verb in the goal (\"contrast\", \"acknowledging\"). Count them. An answer that satisfies only one of two goal verbs is wrong, no matter how well written."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":10}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$ || ':' || '11')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 8: Transitions that look like examples$sat_pb$, 11, $sat_pb${"markdown":"**Worked item 8.**\n\n*Many species of octopus live only a year or two. The giant Pacific octopus, ______, can live for several years, which is long by octopus standards, though still brief compared with many fish of similar size.*\n\nWhich choice completes the text with the most logical transition?\n\n- A) for instance,\n- B) however,\n- C) likewise,\n- D) thus,\n\n**Answer: B.** The second sentence contrasts one species' lifespan with the short lifespans just described.\n\n- **A** is the trap: the giant Pacific octopus is an *instance of an octopus*, but the sentence does not illustrate the first claim; it contradicts it for one species.\n- **C** signals similarity, the opposite relationship.\n- **D** signals a consequence, but nothing in the first sentence causes the second.\n\n**Lesson.** Decide the relationship between the *claims*, not between the nouns. Say it in one word (contrast, cause, example, addition) before reading the choices."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":11}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$ || ':' || '12')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 9: Boundaries edge cases$sat_pb$, 12, $sat_pb${"markdown":"Boundaries questions in the upper module test the rules students half-know. Three original items:\n\n**Worked item 9a.** *The touring orchestra will perform in Lisbon, Portugal ______ Porto, Portugal; and Seville, Spain.*\n\n- A) Portugal;\n- B) Portugal,\n- C) Portugal:\n- D) Portugal\n\n**Answer: A.** When list items already contain commas, the items are separated by semicolons. The rest of the sentence (\"Portugal; and Seville\") confirms the pattern. **B** creates an ambiguous comma list; **C** introduces a list mid-list; **D** runs two items together.\n\n**Worked item 9b.** *The physicist Chien-Shiung Wu, whose 1956 experiment overturned a long-accepted principle of physics ______ later became the first woman to serve as president of the American Physical Society.*\n\n- A) physics—\n- B) physics,\n- C) physics;\n- D) physics\n\n**Answer: B.** The supplementary clause opens with a comma after \"Wu\", so it must close with a comma. **A** mixes a comma with a dash, a classic trap: pairs must match. **C** separates subject from verb with a semicolon. **D** leaves the clause unclosed.\n\n**Worked item 9c.** *The first trial produced no measurable effect ______ the second, conducted at a higher temperature, produced a clear one.*\n\n- A) effect; however,\n- B) effect, however,\n- C) effect however,\n- D) effect, however\n\n**Answer: A.** Two independent clauses joined by a conjunctive adverb need a semicolon (or period) before \"however\" and a comma after it. **B** and **D** are comma splices; **C** has no boundary at all.\n\n**Boundaries rules to have automatic:**\n\n| Situation | Correct boundary |\n|---|---|\n| Two independent clauses, no conjunction | Semicolon or period |\n| Independent clause + list or explanation | Colon (only after a complete clause) |\n| Supplementary element in mid-sentence | Matching pair: two commas, two dashes or two parentheses |\n| List items containing commas | Semicolons between items |\n| Subject and its verb | No punctuation between them |"}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":12}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$ || ':' || '13')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 10: Form, structure and sense$sat_pb$, 13, $sat_pb${"markdown":"**Worked item 10a.** *The collection of letters written by the explorer's crew members during the voyage ______ now housed in the national archive.*\n\n- A) is\n- B) are\n- C) were\n- D) have been\n\n**Answer: A.** The subject is \"collection\" (singular). The nouns between subject and verb (\"letters\", \"members\") are inside modifying phrases. **B**, **C** and **D** agree with the nearest plural noun, which is the whole trap.\n\n**Worked item 10b.** *Having analysed thousands of satellite images, ______*\n\n- A) the researchers concluded that the glacier had retreated faster than expected.\n- B) the glacier's retreat was found to be faster than expected.\n- C) it was concluded that the glacier had retreated faster than expected.\n- D) the conclusion of the researchers was that the glacier had retreated faster than expected.\n\n**Answer: A.** The opening phrase describes whoever analysed the images, so that subject must come right after the comma. **B** makes the glacier's retreat do the analysing; **C** uses an empty \"it\"; **D** makes \"the conclusion\" the analyst.\n\n**Lesson.** For agreement, cross out every phrase between subject and verb. For modifiers, ask \"who is doing the -ing?\" and make sure that noun follows the comma."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":13}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$ || ':' || '14')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Trap family 11: Inference completions$sat_pb$, 14, $sat_pb${"markdown":"**Worked item 11.**\n\n*Researchers found that water fleas raised in water containing chemical traces of predatory fish developed protective helmet-shaped heads, while fleas raised in clean water did not. The helmets make the fleas harder for fish to swallow but also slow their reproduction. These findings suggest that in a lake from which predatory fish have been removed, ______*\n\n- A) most water fleas would not develop helmets, and their reproduction would not be slowed by them.\n- B) water fleas would develop larger helmets to make up for the absence of fish.\n- C) water fleas would be eaten more often than fleas in lakes that contain fish.\n- D) water fleas would stop reproducing altogether.\n\n**Answer: A.** Helmets appear in response to fish chemicals; without fish there are no chemical traces, so helmets would not form, and their reproductive cost would disappear.\n\n- **B** reverses the trigger.\n- **C** contradicts the premise: there are no predatory fish to do the eating.\n- **D** is extreme; the text says helmets *slow* reproduction, and helmets would be absent anyway.\n\n**Lesson.** Inference completions are short chains: premise, mechanism, consequence. Write the chain in five words (\"no fish, no trigger, no helmet\") and pick the choice that ends the chain without adding new causes."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":14}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$ || ':' || '15')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Pacing inside the hard module$sat_pb$, 15, $sat_pb${"markdown":"Thirty-two minutes for 27 questions is about 71 seconds per question on average. Because questions are grouped by skill and ordered from easier to harder within each group, time pressure does not fall evenly.\n\n- **Conventions items** (boundaries, form and sense) should take 30–45 seconds once the rules are automatic. Bank the time.\n- **Cross-text, quantitative and weaken/strengthen items** may need 90 seconds or more. That is fine if conventions were fast.\n- **Mark and move:** if two choices survive after 90 seconds, choose the better one, mark it for review, and continue. Bluebook's question menu shows marked and unanswered questions so you can return before the module ends.\n- **Never leave a blank.** The College Board's assessment framework says the digital SAT has no guessing penalty and advises answering every question as well as you can, eliminating one or two choices when unsure. A blank cannot earn credit."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":15}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$ || ':' || '16')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Using Bluebook tools on hard items$sat_pb$, 16, $sat_pb${"markdown":"Bluebook includes **highlights and notes**, an **option eliminator** to cross out choices, **mark for review**, a **line reader** and a **countdown timer** you can hide until the five-minute alert. On hard questions:\n\n- Use the **option eliminator** after each test of a choice, so you never re-read a rejected choice.\n- **Highlight the claim** in weaken/strengthen and data items; it keeps you on task when the choices drift.\n- **Hide the timer** if it makes you rush, but check it at the end of each skill group."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":16}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$ || ':' || '17')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Error codes for your notebook$sat_pb$, 17, $sat_pb${"markdown":"Record every miss in the [SAT Practice notebook](https://practice.sat.schood.online/notebook) with one code:\n\n| Code | Meaning | Fix |\n|---|---|---|\n| TT | True-but-irrelevant choice accepted | Restate the task before choosing |\n| HG | Half-goal answer in rhetorical synthesis | Count goal verbs |\n| PA | Missed partial agreement in cross-text | Name what Text 2 accepts and rejects |\n| PW | Pivot word missed in structure questions | Circle pivots on first read |\n| NN | Agreed with nearest noun | Cross out intervening phrases |\n| MP | Mismatched punctuation pair | Check the opening mark first |\n| OR | Over-read: answer goes beyond the text | Demand a line that supports every word |"}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":17}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$ || ':' || '18')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Fourteen-day drill block for hard-module R&W$sat_pb$, 18, $sat_pb${"markdown":"- **Days 1–2:** weaken/strengthen and quantitative evidence (items 1–2). 20 hard Information and Ideas items per day in the [SAT Practice Bank](https://practice.sat.schood.online/bank), with a written claim for each.\n- **Days 3–4:** cross-text and structure (items 3, 5, 6).\n- **Day 5:** words in context: 25 hard items, writing the punctuation clue for each.\n- **Days 6–7:** rhetorical synthesis and transitions (items 7–8). Count goal verbs aloud.\n- **Day 8:** one timed 27-question R&W module, then full review with error codes.\n- **Days 9–10:** boundaries and form/structure/sense (items 9–10), 30 items per day, timed at 40 seconds each.\n- **Day 11:** inference completions (item 11) plus a mixed set of 20 hard items.\n- **Day 12:** re-do every missed item from days 1–11 without looking at explanations; clear the [reviews queue](https://practice.sat.schood.online/reviews).\n- **Day 13:** full mock in the [SAT simulator](https://sat.schood.online).\n- **Day 14:** review the mock by code; the most frequent code sets your next block."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":18}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$ || ':' || '19')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$)::uuid, $sat_pb$checklist$sat_pb$, $sat_pb$Self-check before you leave this guide$sat_pb$, 19, $sat_pb${"items":["I state the task in three words before reading the choices.","I can reject a true statement that does not answer the question.","I translate a data claim into the exact comparison it requires.","I name what Text 2 accepts and what it rejects in cross-text items.","I use punctuation as the definition clue in words-in-context items.","I count structural moves using pivot words.","I count the verbs in a rhetorical synthesis goal and require all of them.","I decide the logical relationship before choosing a transition.","I close supplementary elements with the same mark that opened them.","I cross out intervening phrases before choosing a verb."]}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":19}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$ || ':' || '20')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$)::uuid, $sat_pb$rich_text$sat_pb$, $sat_pb$Where to go next$sat_pb$, 20, $sat_pb${"markdown":"- Foundations: [Expression of Ideas](/reading-writing-expression-of-ideas) and [Standard English Conventions](/reading-writing-conventions).\n- Timing: [Pacing and Adaptive Modules](/pacing-and-adaptive-modules).\n- High targets: [1400 to 1550 Roadmap](/guide-1400-to-1550-roadmap).\n- Practice: hard-difficulty sets in [SAT Practice](https://practice.sat.schood.online/bank); full mocks in the [SAT simulator](https://sat.schood.online)."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":20}$sat_pb$::jsonb),
    (md5('schood-sat-pb-section:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$ || ':' || '21')::uuid, md5('schood-sat-pb-page:' || $sat_pb$guide-rw-hard-module-traps$sat_pb$)::uuid, $sat_pb$callout$sat_pb$, $sat_pb$A note on these items$sat_pb$, 21, $sat_pb${"label":"Original practice","body":"Every passage and question here was written by Schood for teaching. Researchers named in the science and history items are fictional; the physics item refers to a real scientist. Nothing is copied or adapted from official or commercial tests. Use official Bluebook practice alongside this guide to see the real interface."}$sat_pb$::jsonb, $sat_pb${"seeded_by":"20261026161000_sat_playbook_premium_guides","content_revision":"sat-pb-premium-2026-10-v1","n":21}$sat_pb$::jsonb)
) as v(id, page_id, block_type, heading, sort_order, content, metadata)
where exists (select 1 from public.sat_playbook_pages p where p.id = v.page_id)
on conflict do nothing;

